"use client";

import { useCallback, useEffect, useState, type KeyboardEvent } from "react";

export interface NavigableItem {
  id: string;
  path: string;
  /** True when `path` is an external URL (course `link`) rather than an in-app route. */
  external?: boolean;
}

interface UseResultsNavigationArgs {
  items: NavigableItem[];
  onSelect: (path: string, external?: boolean) => void;
  onEscape: () => void;
}

/**
 * Arrow-key / Enter / Escape navigation over a flat list of results.
 * Works regardless of how the results are visually grouped — the caller
 * just flattens its cards into `items` in display order.
 */
export function useResultsNavigation({ items, onSelect, onEscape }: UseResultsNavigationArgs) {
  const [activeIndex, setActiveIndex] = useState(-1);

  // Reset selection whenever the result set changes (new query, etc.)
  useEffect(() => {
    setActiveIndex(items.length > 0 ? 0 : -1);
  }, [items]);

  const handleKeyDown = useCallback(
    (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        e.preventDefault();
        onEscape();
        return;
      }

      if (items.length === 0) return;

      switch (e.key) {
        case "ArrowDown":
          e.preventDefault();
          setActiveIndex((prev) => (prev + 1) % items.length);
          break;
        case "ArrowUp":
          e.preventDefault();
          setActiveIndex((prev) => (prev - 1 + items.length) % items.length);
          break;
        case "Enter":
          if (activeIndex >= 0 && items[activeIndex]) {
            e.preventDefault();
            onSelect(items[activeIndex].path, items[activeIndex].external);
          }
          break;
        default:
          break;
      }
    },
    [items, activeIndex, onSelect, onEscape],
  );

  const activeId = activeIndex >= 0 ? items[activeIndex]?.id : undefined;

  return { activeIndex, activeId, handleKeyDown };
}
