import React from "react";
import styles from "./HighlightMatch.module.css";

interface HighlightMatchProps {
  text: string;
  query: string;
}

// Escape special regex characters
function escapeRegExp(input: string): string {
  return input.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

const HighlightMatch: React.FC<HighlightMatchProps> = ({ text, query }) => {
  const trimmedQuery = query.trim();
  if (!trimmedQuery) return <>{text}</>;

  const words = trimmedQuery.split(/\s+/).map(escapeRegExp);
  const splitRegex = new RegExp(`(${words.join("|")})`, "gi");
  const matchRegex = new RegExp(`^(?:${words.join("|")})$`, "i");
  const parts = text.split(splitRegex);

  return (
    <>
      {parts.map((part, i) =>
        matchRegex.test(part) ? (
          <mark key={i} className={styles.highlight}>
            {part}
          </mark>
        ) : (
          part
        ),
      )}
    </>
  );
};

export default HighlightMatch;
