"use client";

import CheckIcon from "@mui/icons-material/Check";
import ContentCopyIcon from "@mui/icons-material/ContentCopy";
import { useEffect, useMemo, useRef, useState, type ReactNode } from "react";

/**
 * A deliberately small markdown renderer for chat answers. It builds React
 * elements (never raw HTML), so model output can't inject markup, and it
 * tolerates half-finished text while an answer is still streaming.
 *
 * Supported: paragraphs, "-" / "1." lists, **bold**, `code`, ``` code blocks.
 * Headings degrade to bold lines; links and images are left as plain text.
 */

type Block =
  | { type: "p"; lines: string[] }
  | { type: "ul" | "ol"; items: string[] }
  | { type: "code"; lang: string; code: string };

const FENCE = /^\s*```\s*([\w+#.-]*)\s*$/;
const BULLET = /^\s*[-*\u2022]\s+(.*)$/;
const NUMBERED = /^\s*\d+[.)]\s+(.*)$/;
const HEADING = /^\s*#{1,6}\s+(.*)$/;

function parseBlocks(text: string): Block[] {
  const lines = text.replace(/\r\n?/g, "\n").split("\n");
  const blocks: Block[] = [];
  let i = 0;

  while (i < lines.length) {
    const line = lines[i];

    const fence = FENCE.exec(line);
    if (fence) {
      const code: string[] = [];
      i++;
      // An unclosed fence (still streaming) renders as code so far.
      while (i < lines.length && !FENCE.test(lines[i])) code.push(lines[i++]);
      i++; // closing fence
      blocks.push({ type: "code", lang: fence[1], code: code.join("\n") });
      continue;
    }

    if (!line.trim()) {
      i++;
      continue;
    }

    const bullet = BULLET.exec(line);
    const numbered = bullet ? null : NUMBERED.exec(line);
    if (bullet || numbered) {
      const pattern = bullet ? BULLET : NUMBERED;
      const items: string[] = [];
      while (i < lines.length) {
        const match = pattern.exec(lines[i]);
        if (!match) break;
        items.push(match[1]);
        i++;
      }
      blocks.push({ type: bullet ? "ul" : "ol", items });
      continue;
    }

    const heading = HEADING.exec(line);
    if (heading) {
      blocks.push({ type: "p", lines: [`**${heading[1].replace(/\*\*/g, "")}**`] });
      i++;
      continue;
    }

    const paragraph: string[] = [];
    while (
      i < lines.length &&
      lines[i].trim() &&
      !FENCE.test(lines[i]) &&
      !BULLET.test(lines[i]) &&
      !NUMBERED.test(lines[i]) &&
      !HEADING.test(lines[i])
    ) {
      paragraph.push(lines[i++]);
    }
    blocks.push({ type: "p", lines: paragraph });
  }

  return blocks;
}

function renderInline(text: string): ReactNode[] {
  return text.split(/(`[^`]+`|\*\*[^*]+\*\*)/g).map((part, i) => {
    if (part.length > 2 && part.startsWith("`") && part.endsWith("`")) {
      return <code key={i}>{part.slice(1, -1)}</code>;
    }
    if (part.length > 4 && part.startsWith("**") && part.endsWith("**")) {
      return <strong key={i}>{part.slice(2, -2)}</strong>;
    }
    return part;
  });
}

function renderLines(lines: string[]): ReactNode[] {
  return lines.flatMap((line, i) => [
    ...(i > 0 ? [<br key={`br${i}`} />] : []),
    ...renderInline(line.trim()),
  ]);
}

function CodeBlock({ lang, code }: { lang: string; code: string }) {
  const [copied, setCopied] = useState(false);
  const timer = useRef<number | undefined>(undefined);

  useEffect(() => () => window.clearTimeout(timer.current), []);

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(code);
      setCopied(true);
      window.clearTimeout(timer.current);
      timer.current = window.setTimeout(() => setCopied(false), 1500);
    } catch {
      /* clipboard blocked: nothing useful to do */
    }
  };

  return (
    <div className="ai-code">
      <div className="ai-code-bar">
        <span>{lang || "code"}</span>
        <button
          type="button"
          className="ai-code-copy"
          onClick={copy}
          onMouseDown={(e) => e.preventDefault()}
          aria-label="Copy code"
        >
          {copied ? (
            <CheckIcon fontSize="inherit" aria-hidden="true" />
          ) : (
            <ContentCopyIcon fontSize="inherit" aria-hidden="true" />
          )}
          {copied ? "Copied" : "Copy"}
        </button>
      </div>
      <pre tabIndex={0}>
        <code>{code}</code>
      </pre>
    </div>
  );
}

interface AiMarkdownProps {
  text: string;
  /** Shows the blinking caret at the end of the last block. */
  caret?: ReactNode;
}

export default function AiMarkdown({ text, caret }: AiMarkdownProps) {
  const blocks = useMemo(() => parseBlocks(text), [text]);
  const last = blocks.length - 1;

  return (
    <>
      {blocks.map((block, i) => {
        const tail = i === last ? caret : null;

        if (block.type === "code") {
          return (
            <div key={i}>
              <CodeBlock lang={block.lang} code={block.code} />
              {tail}
            </div>
          );
        }

        if (block.type === "p") {
          return (
            <p key={i}>
              {renderLines(block.lines)}
              {tail}
            </p>
          );
        }

        const List = block.type;
        return (
          <List key={i}>
            {block.items.map((item, j) => (
              <li key={j}>
                {renderInline(item)}
                {j === block.items.length - 1 ? tail : null}
              </li>
            ))}
          </List>
        );
      })}
    </>
  );
}
