/** A page the user can revisit: shared by "Recently visited" and "Favorites". */
export interface SavedPage {
  /** In-app route (e.g. `/learn/...`) or, when `external` is true, an http(s) URL. */
  path: string;
  /** Topic name, or the course name for course-level / external pages. */
  title: string;
  category: string;
  /** Parent course, present when `title` is a topic inside it. */
  course?: string;
  external?: boolean;
}

const SAFE_INTERNAL_PATH = /^\/(?!\/)/; // "/foo" yes, "//evil.com" no
const SAFE_EXTERNAL_URL = /^https?:\/\//i; // blocks javascript:, data:, etc.

/**
 * Stored values come from localStorage, which anyone can edit, and `path`
 * ends up in `router.push` / `window.open`. Validate shape *and* URL scheme.
 */
export function isSavedPage(value: unknown): value is SavedPage {
  if (!value || typeof value !== "object") return false;
  const page = value as Record<string, unknown>;

  if (typeof page.path !== "string" || typeof page.title !== "string") return false;
  if (typeof page.category !== "string") return false;
  if (page.course !== undefined && typeof page.course !== "string") return false;
  if (page.external !== undefined && typeof page.external !== "boolean") return false;

  return page.external ? SAFE_EXTERNAL_URL.test(page.path) : SAFE_INTERNAL_PATH.test(page.path);
}

export const getPageId = (page: SavedPage) => page.path;

/** Text shown under a page title, e.g. "react / React Basics". */
export function describePage(page: SavedPage): string {
  return page.course ? `${page.category} / ${page.course}` : page.category;
}
