import { createRoute } from "~/utils/slug";
import type { AiImage } from "./aiImages";
import { isSavedPage, type SavedPage } from "./savedPage";
import type { AiCandidate } from "./searchEngine";

export const AI_ENDPOINT = "/api/search/ai";
export const AI_MIN_QUESTION_LENGTH = 2;
export const AI_MAX_QUESTION_LENGTH = 300;
/** How many earlier exchanges (question + answer) are sent along for follow-ups. */
export const AI_MAX_HISTORY_TURNS = 6;
/** The topic lookup is only a helper: past this we give up and search with the typed words alone. */
export const AI_TOPICS_TIMEOUT_MS = 8_000;
/** Earlier messages sent to the topic lookup, enough to resolve "and in Python?". */
const AI_TOPICS_HISTORY_ITEMS = 4;
const AI_TOPICS_MAX_KEYWORDS = 15;

/**
 * Starter questions on the empty AI screen. They span Pinktra's domains and
 * touch a product and the services, so the first impression matches the
 * whole platform rather than just programming.
 */
export const AI_STARTERS = [
  "How do I build a habit that sticks?",
  "What is a trading journal and how do I use one?",
  "Where should I start learning to code?",
  "I need a website built for my business",
];

/** One earlier message in the conversation, sent as text only (no images). */
export interface AiHistoryItem {
  role: "user" | "model";
  text: string;
}

/** Shape sent to the server route. `id` is only meaningful within one request. */
export interface AiContextItem {
  id: string;
  title: string;
  course?: string;
  category: string;
  description: string;
}

/** Builds the same routes `Search.tsx` uses for regular results. */
export function candidateToPage(candidate: AiCandidate): SavedPage {
  const { category, name, topic, firstTopicPath, link, path } = candidate;

  if (link) return { path: link, title: name, category, external: true };

  if (topic) {
    return {
      path: path ?? createRoute("learn", category, name, topic),
      title: topic,
      category,
      course: name,
    };
  }

  const coursePath = firstTopicPath ? firstTopicPath : createRoute("learn", category, name);

  return { path: coursePath, title: name, category };
}

function toContextItem(candidate: AiCandidate, position: number): AiContextItem {
  return {
    id: String(position + 1),
    title: candidate.topic ?? candidate.name,
    course: candidate.topic ? candidate.name : undefined,
    category: candidate.category,
    description: candidate.description,
  };
}

/** What the AI understood the message to be about, used to search the page index. */
export interface AiTopics {
  subject: string;
  /** Search terms, most important first. */
  keywords: string[];
}

/**
 * Step 1 of an AI question: asks the server what the message (and any image)
 * is really about, as a subject plus search keywords. The page index lives in
 * the browser, so the keywords are used here to find the right pages before
 * the answer is requested. This is what makes "anchor tag" find "HTML Link
 * Page", and an image of CSS code find the CSS course.
 *
 * Never throws: on any failure (network, timeout, rate limit) it returns null
 * and the caller falls back to searching with the typed words alone.
 */
export async function fetchAiTopics(
  {
    question,
    history,
    images,
  }: { question: string; history: AiHistoryItem[]; images: AiImage[] },
  signal: AbortSignal,
): Promise<AiTopics | null> {
  const controller = new AbortController();
  const onAbort = () => controller.abort();
  signal.addEventListener("abort", onAbort, { once: true });
  if (signal.aborted) controller.abort();
  const timer = setTimeout(() => controller.abort(), AI_TOPICS_TIMEOUT_MS);

  try {
    const response = await fetch(AI_ENDPOINT, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        mode: "topics",
        question,
        history: history.slice(-AI_TOPICS_HISTORY_ITEMS),
        images: images.map(({ mimeType, data }) => ({ mimeType, data })),
      }),
      signal: controller.signal,
    });
    if (!response.ok) return null;

    const data = (await response.json()) as { subject?: unknown; keywords?: unknown };
    const keywords = Array.isArray(data.keywords)
      ? data.keywords
          .filter((keyword): keyword is string => typeof keyword === "string" && keyword.trim().length > 1)
          .slice(0, AI_TOPICS_MAX_KEYWORDS)
      : [];

    return { subject: typeof data.subject === "string" ? data.subject : "", keywords };
  } catch {
    return null;
  } finally {
    clearTimeout(timer);
    signal.removeEventListener("abort", onAbort);
  }
}

export type AiStreamEvent =
  { type: "delta"; text: string } | { type: "sources"; sources: SavedPage[] };

/**
 * Turns one NDJSON line from the server into an event. The model only ever
 * returns *ids* of the pages it was given; paths are rebuilt here from our
 * own data, so a hallucinated or injected URL can never reach `router.push`
 * or `window.open`.
 */
function parseLine(line: string, candidates: AiCandidate[]): AiStreamEvent | null {
  if (!line.trim()) return null;

  let event: {
    type?: unknown;
    text?: unknown;
    ids?: unknown;
    catalog?: unknown;
    message?: unknown;
  };
  try {
    event = JSON.parse(line);
  } catch {
    return null;
  }

  if (event.type === "delta" && typeof event.text === "string") {
    return { type: "delta", text: event.text };
  }

  if (event.type === "sources" && Array.isArray(event.ids)) {
    // Product / service pages come pre-resolved from the server (static site data).
    const catalog = new Map<string, SavedPage>();
    if (Array.isArray(event.catalog)) {
      for (const raw of event.catalog as unknown[]) {
        if (!raw || typeof raw !== "object") continue;
        const { id, ...page } = raw as Record<string, unknown>;
        if (typeof id === "string" && isSavedPage(page)) catalog.set(id, page);
      }
    }

    const seen = new Set<string>();
    const sources: SavedPage[] = [];

    for (const rawId of event.ids) {
      const id = String(rawId);
      const candidate = candidates[Number(id) - 1];
      const page = catalog.get(id) ?? (candidate ? candidateToPage(candidate) : null);
      if (!page || !isSavedPage(page) || seen.has(page.path)) continue;

      seen.add(page.path);
      sources.push(page);
    }

    return { type: "sources", sources };
  }

  if (event.type === "error") {
    throw new Error(
      typeof event.message === "string" ? event.message : "The AI failed to respond.",
    );
  }

  return null;
}

export interface StreamAiAnswerParams {
  question: string;
  candidates: AiCandidate[];
  /** Earlier messages, oldest first, ending with a model reply. */
  history: AiHistoryItem[];
  /** Images attached to this message only. */
  images: AiImage[];
}

/**
 * Streams an answer: yields `delta` events as text arrives, then one final
 * `sources` event. Throws on HTTP or in-stream errors.
 */
export async function* streamAiAnswer(
  { question, candidates, history, images }: StreamAiAnswerParams,
  signal: AbortSignal,
): AsyncGenerator<AiStreamEvent> {
  const response = await fetch(AI_ENDPOINT, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      question,
      context: candidates.map(toContextItem),
      history,
      images: images.map(({ mimeType, data }) => ({ mimeType, data })),
    }),
    signal,
  });

  if (!response.ok) {
    const body = (await response.json().catch(() => null)) as { error?: unknown } | null;
    throw new Error(
      typeof body?.error === "string" ? body.error : "AI answers are unavailable right now.",
    );
  }
  if (!response.body) throw new Error("The AI returned an unexpected response.");

  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";

  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;

      buffer += decoder.decode(value, { stream: true });

      // A network chunk can end mid-line; keep the tail for the next read.
      const lines = buffer.split("\n");
      buffer = lines.pop() ?? "";

      for (const line of lines) {
        const event = parseLine(line, candidates);
        if (event) yield event;
      }
    }

    buffer += decoder.decode();
    const last = parseLine(buffer, candidates);
    if (last) yield last;
  } finally {
    // Also runs when the consumer stops early, which closes the connection.
    reader.cancel().catch(() => {});
  }
}
