"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import type { AiImage } from "./aiImages";
import {
  AI_MAX_HISTORY_TURNS,
  AI_MAX_QUESTION_LENGTH,
  AI_MIN_QUESTION_LENGTH,
  fetchAiTopics,
  streamAiAnswer,
  type AiHistoryItem,
} from "./aiSearch";
import { isSavedPage, type SavedPage } from "./savedPage";
import { retrieveForAI, type FlatSearchEntry } from "./searchEngine";

/** One exchange: what the user sent and Pia's (possibly still streaming) reply. */
export interface ChatTurn {
  id: string;
  /** May be empty when the user sent only images. */
  question: string;
  /** Full image data. Only held in memory: not saved, so empty after a reload. */
  images: AiImage[];
  /** How many images were attached, even if their data is gone after a reload. */
  imageCount: number;
  /**
   * loading   - request sent, no text yet
   * streaming - text is arriving; sources come at the end
   * done      - complete
   * error     - failed or stopped; can be retried
   */
  status: "loading" | "streaming" | "done" | "error";
  /**
   * True when "thinking" was on for this message: the AI first works out the
   * topic (a second AI call) so better pages are found. False is the plain
   * single-call path.
   */
  thinking: boolean;
  answer: string;
  sources: SavedPage[];
  error?: string;
}

export const AI_CHAT_KEY = "search:ai-chat";
const MAX_STORED_TURNS = 20;

/** Images can't be re-sent after a reload, so those turns can't be retried. */
export const canRetryTurn = (turn: ChatTurn) => turn.imageCount === turn.images.length;

/** Guards what comes back from localStorage, which anyone can edit. */
function isStoredTurn(value: unknown): value is ChatTurn {
  if (!value || typeof value !== "object") return false;
  const turn = value as Record<string, unknown>;

  return (
    typeof turn.id === "string" &&
    typeof turn.question === "string" &&
    typeof turn.answer === "string" &&
    (turn.status === "done" || turn.status === "error") &&
    (turn.error === undefined || typeof turn.error === "string") &&
    // Turns saved before the thinking option existed have no flag.
    (turn.thinking === undefined || typeof turn.thinking === "boolean") &&
    typeof turn.imageCount === "number" &&
    Array.isArray(turn.sources) &&
    turn.sources.every(isSavedPage)
  );
}

function readStoredTurns(): ChatTurn[] {
  try {
    const raw = window.localStorage.getItem(AI_CHAT_KEY);
    if (!raw) return [];

    const parsed: unknown = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];

    return parsed
      .filter(isStoredTurn)
      .slice(-MAX_STORED_TURNS)
      .map((turn) => ({
        ...turn,
        thinking: turn.thinking === true,
        images: [],
        imageCount: Math.max(0, Math.min(turn.imageCount, 3)),
      }));
  } catch {
    return [];
  }
}

const makeId = () => Math.random().toString(36).slice(2) + Date.now().toString(36);

const isBusy = (turn: ChatTurn | undefined) =>
  turn?.status === "loading" || turn?.status === "streaming";

/** Text-only transcript of finished exchanges, for follow-up questions. */
function buildHistory(prior: ChatTurn[]): AiHistoryItem[] {
  return prior
    .filter((turn) => turn.status === "done" && turn.answer.trim())
    .slice(-AI_MAX_HISTORY_TURNS)
    .flatMap((turn): AiHistoryItem[] => {
      const note = turn.imageCount
        ? `[attached ${turn.imageCount} image${turn.imageCount > 1 ? "s" : ""}]`
        : "";
      const text = [turn.question, note].filter(Boolean).join(" ");
      return [
        { role: "user", text },
        { role: "model", text: turn.answer },
      ];
    });
}

/**
 * Runs a multi-turn conversation with Pia, one request at a time. Each
 * question retrieves candidate pages locally, streams the answer from
 * `/api/search/ai`, and appends to `turns`. Earlier turns are sent as
 * text-only history so follow-ups ("explain more", "why?") work; images are
 * only sent with the message they were attached to.
 */
export function useAiChat(index: FlatSearchEntry[]) {
  const [turns, setTurns] = useState<ChatTurn[]>([]);
  // Mirror of the latest turns so callbacks stay stable and never read stale state.
  const turnsRef = useRef<ChatTurn[]>([]);
  const abortRef = useRef<AbortController | null>(null);

  const commit = useCallback((updater: (current: ChatTurn[]) => ChatTurn[]) => {
    const next = updater(turnsRef.current);
    turnsRef.current = next;
    setTurns(next);
  }, []);

  const patchTurn = useCallback(
    (id: string, patch: Partial<ChatTurn>) =>
      commit((current) => current.map((turn) => (turn.id === id ? { ...turn, ...patch } : turn))),
    [commit],
  );

  /** Streams the reply for `turn`, using `prior` (the turns before it) as context. */
  const run = useCallback(
    async (turn: ChatTurn, prior: ChatTurn[]) => {
      abortRef.current?.abort();
      const controller = new AbortController();
      abortRef.current = controller;
      const isCurrent = () => abortRef.current === controller;

      try {
        // A short follow-up ("and in Python?") says little on its own, so
        // retrieve pages using the previous question as well.
        const previousQuestion = [...prior].reverse().find((t) => t.question)?.question;
        const wordCount = turn.question.split(/\s+/).filter(Boolean).length;
        const retrievalQuery =
          previousQuestion && wordCount <= 6
            ? `${previousQuestion} ${turn.question}`
            : turn.question;
        const history = buildHistory(prior);

        // Thinking on: a first AI call works out what the message (or image) is
        // about, so pages are found by meaning instead of by the typed words
        // alone. It fails soft: null just means "search with the typed words".
        // Thinking off: skip it, so the whole question costs a single AI call.
        const topics = turn.thinking
          ? await fetchAiTopics(
              { question: turn.question, history, images: turn.images },
              controller.signal,
            )
          : null;
        if (!isCurrent()) return;

        // Search the local index with the typed words (plus the AI's keywords, if any).
        const candidates = retrieveForAI(index, retrievalQuery, { topics: topics?.keywords });

        let answer = "";
        let sources: SavedPage[] = [];

        const events = streamAiAnswer(
          { question: turn.question, candidates, history, images: turn.images },
          controller.signal,
        );

        for await (const event of events) {
          if (!isCurrent()) return;

          if (event.type === "delta") {
            answer += event.text;
            patchTurn(turn.id, { status: "streaming", answer });
          } else {
            sources = event.sources;
          }
        }

        if (!isCurrent()) return;
        if (!answer.trim()) {
          throw new Error("The AI couldn't produce an answer. Try rephrasing your question.");
        }

        patchTurn(turn.id, { status: "done", answer: answer.trim(), sources });
      } catch (error) {
        // Superseded by a newer request, stopped by the user, or the modal closed.
        if (controller.signal.aborted || !isCurrent()) return;

        patchTurn(turn.id, {
          status: "error",
          error: error instanceof Error ? error.message : "Something went wrong.",
        });
      } finally {
        if (isCurrent()) abortRef.current = null;
      }
    },
    [index, patchTurn],
  );

  const ask = useCallback(
    (rawQuestion: string, images: AiImage[] = [], thinking = false) => {
      const question = rawQuestion.trim().replace(/\s+/g, " ").slice(0, AI_MAX_QUESTION_LENGTH);
      const hasImages = images.length > 0;

      if (!hasImages && question.length < AI_MIN_QUESTION_LENGTH) return;
      if (isBusy(turnsRef.current[turnsRef.current.length - 1])) return;

      const prior = turnsRef.current;
      const turn: ChatTurn = {
        id: makeId(),
        question,
        images,
        imageCount: images.length,
        thinking,
        status: "loading",
        answer: "",
        sources: [],
      };

      commit((current) => [...current, turn]);
      void run(turn, prior);
    },
    [commit, run],
  );

  /**
   * Re-asks the last question: used by "Try again" and "Regenerate". Pass
   * `thinking` to retry with a different mode (e.g. turn thinking on after a
   * weak answer); by default the turn keeps the mode it was first asked with.
   */
  const regenerate = useCallback(
    (thinking?: boolean) => {
      const current = turnsRef.current;
      const last = current[current.length - 1];
      if (!last || isBusy(last) || !canRetryTurn(last)) return;

      const prior = current.slice(0, -1);
      const fresh: ChatTurn = {
        ...last,
        thinking: thinking ?? last.thinking,
        status: "loading",
        answer: "",
        sources: [],
        error: undefined,
      };

      commit(() => [...prior, fresh]);
      void run(fresh, prior);
    },
    [commit, run],
  );

  /** Stops the reply in progress, keeping whatever text has arrived. */
  const stop = useCallback(() => {
    const last = turnsRef.current[turnsRef.current.length - 1];
    if (!last || !isBusy(last)) return;

    abortRef.current?.abort();
    abortRef.current = null;

    if (last.answer.trim()) {
      patchTurn(last.id, { status: "done", answer: last.answer.trim(), sources: [] });
    } else {
      patchTurn(last.id, { status: "error", error: "Stopped before an answer arrived." });
    }
  }, [patchTurn]);

  /** Starts a new chat: aborts any request and clears the conversation. */
  const reset = useCallback(() => {
    abortRef.current?.abort();
    abortRef.current = null;
    commit(() => []);
  }, [commit]);

  // Restore the saved conversation after mount (so server and client markup
  // match), then keep it saved. Nothing is written before the restore has run,
  // so an empty start can't wipe what was saved.
  const [hydrated, setHydrated] = useState(false);

  useEffect(() => {
    const stored = readStoredTurns();
    if (stored.length > 0 && turnsRef.current.length === 0) {
      turnsRef.current = stored;
      setTurns(stored);
    }
    setHydrated(true);
  }, []);

  useEffect(() => {
    if (!hydrated) return;
    // Save only settled conversations: re-writing on every streamed token is
    // wasteful, and a half-finished turn is useless after a reload anyway.
    if (turns.some(isBusy)) return;

    try {
      if (turns.length === 0) window.localStorage.removeItem(AI_CHAT_KEY);
      else {
        const saved = turns.slice(-MAX_STORED_TURNS).map(({ images: _images, ...rest }) => rest);
        window.localStorage.setItem(AI_CHAT_KEY, JSON.stringify(saved));
      }
    } catch {
      /* storage full or unavailable: this is a convenience feature */
    }
  }, [turns, hydrated]);

  // Cancel any in-flight request on unmount.
  useEffect(() => () => abortRef.current?.abort(), []);

  const busy = isBusy(turns[turns.length - 1]);

  return { turns, busy, ask, regenerate, stop, reset };
}
