"use client";

import ArrowForwardIcon from "@mui/icons-material/ArrowForward";
import AutoAwesomeIcon from "@mui/icons-material/AutoAwesome";
import CheckIcon from "@mui/icons-material/Check";
import ContentCopyIcon from "@mui/icons-material/ContentCopy";
import RefreshIcon from "@mui/icons-material/Refresh";
import {
  useEffect,
  useRef,
  useState,
  type CSSProperties,
  type MouseEvent,
  type ReactNode,
} from "react";
import AiMarkdown from "./AiMarkdown";
import type { SavedPage } from "./savedPage";
import PageRow from "./SearchPageRow";
import { canRetryTurn, type ChatTurn } from "./useAiChat";

export const AI_NAME = "Pia";

interface SearchAiPanelProps {
  turns: ChatTurn[];
  /** Short notice shown above the chat, e.g. when the input is too short. */
  hint?: string | null;
  /** Example questions shown before the first message. */
  suggestions: string[];
  favoritePaths: Set<string>;
  onAsk: (question: string) => void;
  onOpenSource: (page: SavedPage, opts: { newTab: boolean }) => void;
  onToggleFavorite: (page: SavedPage) => void;
  /** Re-asks the last question (used by "Try again" and "Regenerate"). */
  onRegenerate: () => void;
  /** True while the modal is visible; used to scroll to the latest message on open. */
  active: boolean;
}

const AI_DISCLAIMER = `${AI_NAME} is AI and can make mistakes. Answers are for learning, not medical, financial or trading advice.`;

// Keep focus in the search input when buttons are pressed (the click still fires).
const keepInputFocus = (e: MouseEvent<HTMLElement>) => e.preventDefault();

/** The assistant's mark: a slowly swirling orb that speeds up while it works. */
function PiaOrb({ size = "sm", busy = false }: { size?: "sm" | "lg"; busy?: boolean }) {
  return (
    <span className={`pia-orb ${size} ${busy ? "busy" : ""}`} aria-hidden="true">
      <AutoAwesomeIcon className="pia-orb-icon" />
    </span>
  );
}

function AssistantHead({ busy }: { busy: boolean }) {
  return (
    <div className="ai-assistant-head">
      <PiaOrb busy={busy} />
      <span className="ai-assistant-name">{AI_NAME}</span>
      <span className="ai-assistant-badge">AI</span>
    </div>
  );
}

function UserMessage({ turn }: { turn: ChatTurn }) {
  return (
    <div className="ai-user-row">
      <div className="ai-user-message">
        {turn.images.length > 0 && (
          <ul className={`ai-user-images count-${turn.images.length}`}>
            {turn.images.map((image, i) => (
              <li key={image.id}>
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img src={image.previewUrl} alt={`Your attached image ${i + 1}`} />
              </li>
            ))}
          </ul>
        )}
        {turn.images.length === 0 && turn.imageCount > 0 && (
          <p className="ai-user-note">
            {turn.imageCount} image{turn.imageCount > 1 ? "s" : ""} attached (not saved)
          </p>
        )}
        {turn.question && <p className="ai-user-bubble">{turn.question}</p>}
      </div>
    </div>
  );
}

function ActionButton({
  label,
  onClick,
  children,
}: {
  label: string;
  onClick: () => void;
  children: ReactNode;
}) {
  return (
    <button
      type="button"
      className="ai-action"
      onClick={onClick}
      onMouseDown={keepInputFocus}
      aria-label={label}
      title={label}
    >
      {children}
    </button>
  );
}

function CopyAnswerButton({ text }: { text: string }) {
  const [copied, setCopied] = useState(false);
  const timer = useRef<number | undefined>(undefined);

  useEffect(() => () => window.clearTimeout(timer.current), []);

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(text);
      setCopied(true);
      window.clearTimeout(timer.current);
      timer.current = window.setTimeout(() => setCopied(false), 1500);
    } catch {
      /* clipboard blocked: nothing useful to do */
    }
  };

  return (
    <ActionButton label={copied ? "Copied" : "Copy answer"} onClick={copy}>
      {copied ? (
        <CheckIcon fontSize="inherit" aria-hidden="true" />
      ) : (
        <ContentCopyIcon fontSize="inherit" aria-hidden="true" />
      )}
    </ActionButton>
  );
}

interface TurnViewProps {
  turn: ChatTurn;
  isLast: boolean;
  favoritePaths: Set<string>;
  onOpenSource: SearchAiPanelProps["onOpenSource"];
  onToggleFavorite: SearchAiPanelProps["onToggleFavorite"];
  onRegenerate: () => void;
}

function TurnView({
  turn,
  isLast,
  favoritePaths,
  onOpenSource,
  onToggleFavorite,
  onRegenerate,
}: TurnViewProps) {
  const streaming = turn.status === "streaming";

  return (
    <div className="ai-turn">
      <UserMessage turn={turn} />

      <div className="ai-assistant">
        <AssistantHead busy={turn.status === "loading" || streaming} />

        {turn.status === "loading" && (
          <div role="status" aria-live="polite">
            <p className="pia-thinking">{turn.images.length > 0 ? "Looking at your image…" : "Thinking…"}</p>
            <div className="skeleton-line ai-skeleton" />
            <div className="skeleton-line ai-skeleton" />
            <div className="skeleton-line ai-skeleton short" />
          </div>
        )}

        {turn.status === "error" && (
          <div className="ai-error">
            <p role="alert">{turn.error ?? "Something went wrong."}</p>
            {isLast && canRetryTurn(turn) && (
              <button type="button" className="category-chip" onClick={onRegenerate}>
                Try again
              </button>
            )}
          </div>
        )}

        {(streaming || turn.status === "done") && (
          // aria-busy holds back screen-reader announcements until the text is complete.
          <div className="ai-answer-body" aria-live="polite" aria-busy={streaming}>
            <AiMarkdown
              text={turn.answer}
              caret={streaming ? <span className="pia-caret" aria-hidden="true" /> : null}
            />
          </div>
        )}

        {turn.status === "done" && turn.sources.length > 0 && (
          <section className="ai-sources" aria-label="Sources">
            <div className="recent-header">
              <h2 className="recent-title">Explore next</h2>
            </div>
            <ul className="recent-list">
              {turn.sources.map((page) => (
                <PageRow
                  key={page.path}
                  page={page}
                  isFavorite={favoritePaths.has(page.path)}
                  onOpen={(opts) => onOpenSource(page, opts)}
                  onToggleFavorite={() => onToggleFavorite(page)}
                />
              ))}
            </ul>
          </section>
        )}

        {turn.status === "done" && (
          <div className="ai-actions">
            <CopyAnswerButton text={turn.answer} />
            {isLast && canRetryTurn(turn) && (
              <ActionButton label="Regenerate answer" onClick={onRegenerate}>
                <RefreshIcon fontSize="inherit" aria-hidden="true" />
              </ActionButton>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

function Hero({
  suggestions,
  onAsk,
}: Pick<SearchAiPanelProps, "suggestions" | "onAsk">) {
  return (
    <div className="pia-hero">
      <PiaOrb size="lg" />
      <p className="pia-eyebrow">Pinktra assistant</p>
      <h2 className="pia-title">Ask {AI_NAME}</h2>
      <p className="pia-subtitle">
        Ask about anything on Pinktra, from technology and finance to health and productivity, and
        keep the conversation going with follow-ups. You can also attach, paste or drop a
        screenshot or photo and ask about it.
      </p>

      {suggestions.length > 0 && (
        <ul className="pia-suggestions">
          {suggestions.map((question, i) => (
            <li key={question} style={{ "--i": i } as CSSProperties}>
              <button type="button" className="pia-suggestion" onClick={() => onAsk(question)}>
                <span>{question}</span>
                <ArrowForwardIcon fontSize="small" aria-hidden="true" />
              </button>
            </li>
          ))}
        </ul>
      )}

      <p className="ai-disclaimer">{AI_DISCLAIMER}</p>
    </div>
  );
}

/**
 * Keeps the newest message in view like a chat app: jumps to the end when the
 * modal opens (the restored conversation starts at the latest message, not the
 * first), animates to the end when a message is sent, then follows the
 * streaming text unless the user scrolled up to read something earlier.
 */
function useChatScroll(turns: ChatTurn[], active: boolean) {
  const endRef = useRef<HTMLDivElement>(null);
  const stick = useRef(true);

  const last = turns[turns.length - 1];
  const turnCount = turns.length;
  const previousCount = useRef(turnCount);

  const getScroller = () => endRef.current?.closest<HTMLElement>(".search-results") ?? null;

  // Track whether the reader is at (or near) the bottom.
  useEffect(() => {
    const scroller = getScroller();
    if (!scroller) return;

    const onScroll = () => {
      const gap = scroller.scrollHeight - scroller.scrollTop - scroller.clientHeight;
      stick.current = gap < 80;
    };
    scroller.addEventListener("scroll", onScroll, { passive: true });
    return () => scroller.removeEventListener("scroll", onScroll);
  }, []);

  // Opening the modal, or switching to Pia, lands on the latest message at once.
  // A hidden modal has no layout (scrollHeight is 0), so this waits until it's visible.
  useEffect(() => {
    if (!active) return;

    const frame = requestAnimationFrame(() => {
      const scroller = getScroller();
      if (!scroller) return;
      stick.current = true;
      scroller.scrollTop = scroller.scrollHeight;
    });
    return () => cancelAnimationFrame(frame);
  }, [active]);

  // A newly sent message scrolls to the bottom smoothly.
  useEffect(() => {
    const grew = turnCount > previousCount.current;
    previousCount.current = turnCount;
    if (!grew || !active) return;

    const scroller = getScroller();
    if (!scroller) return;

    stick.current = true;
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    scroller.scrollTo({ top: scroller.scrollHeight, behavior: reduced ? "auto" : "smooth" });
  }, [turnCount, active]);

  // New text follows along only while the reader is at the bottom.
  useEffect(() => {
    const scroller = getScroller();
    if (scroller && active && stick.current) scroller.scrollTop = scroller.scrollHeight;
  }, [last?.answer, last?.status, last?.sources.length, active]);

  return endRef;
}

export default function SearchAiPanel({
  turns,
  hint,
  suggestions,
  favoritePaths,
  onAsk,
  onOpenSource,
  onToggleFavorite,
  onRegenerate,
  active,
}: SearchAiPanelProps) {
  const endRef = useChatScroll(turns, active);
  const last = turns[turns.length - 1];
  const idle = last?.status === "done" || last?.status === "error";

  return (
    <>
      {hint && (
        <p className="ai-note" role="status">
          {hint}
        </p>
      )}

      {turns.length === 0 ? (
        <Hero suggestions={suggestions} onAsk={onAsk} />
      ) : (
        <div className="ai-chat" role="log" aria-label={`Conversation with ${AI_NAME}`}>
          {turns.map((turn, i) => (
            <TurnView
              key={turn.id}
              turn={turn}
              isLast={i === turns.length - 1}
              favoritePaths={favoritePaths}
              onOpenSource={onOpenSource}
              onToggleFavorite={onToggleFavorite}
              onRegenerate={onRegenerate}
            />
          ))}
          {idle && <p className="ai-disclaimer">{AI_DISCLAIMER}</p>}
        </div>
      )}

      <div ref={endRef} aria-hidden="true" />
    </>
  );
}
