"use client";

import mainData from "@main-data";
import AddCommentOutlinedIcon from "@mui/icons-material/AddCommentOutlined";
import ArrowForwardIcon from "@mui/icons-material/ArrowForward";
import AutoAwesomeIcon from "@mui/icons-material/AutoAwesome";
import CloseIcon from "@mui/icons-material/Close";
import HistoryIcon from "@mui/icons-material/History";
import KeyboardArrowDownIcon from "@mui/icons-material/KeyboardArrowDown";
import KeyboardArrowUpIcon from "@mui/icons-material/KeyboardArrowUp";
import KeyboardReturnIcon from "@mui/icons-material/KeyboardReturn";
import OpenInNewIcon from "@mui/icons-material/OpenInNew";
import { useRouter } from "next/navigation";
import {
  forwardRef,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type DragEvent,
  type MouseEvent,
} from "react";
import { pushClientPath } from "~/features/learning/lib/remote";
import { useDebounce } from "~/hooks/useDebounce";
import type { MainDataType } from "~/model/main_data_model";
import { normalizeSearch, toTitleCase } from "~/utils/custom_string";
import { createRoute } from "~/utils/slug";
import HighlightMatch from "../HighlightMatch";
import SearchBar from "../SearchBar/SearchBar";
import { AI_MIN_QUESTION_LENGTH, AI_STARTERS } from "./aiSearch";
import { SEARCH_LENGTH } from "./const";
import { type SavedPage } from "./savedPage";
import "./Search.css";
import SearchAiInput from "./SearchAiInput";
import SearchAiPanel, { AI_NAME } from "./SearchAiPanel";
import {
  searchContent,
  suggestQueries,
  warmSearchIndex,
  type FlatSearchEntry,
} from "./searchEngine";
import PageRow, { FavoriteToggle, isModifiedClick } from "./SearchPageRow";
import { useAiChat } from "./useAiChat";
import { useFavoritePages } from "./useFavoritePages";
import { useImageAttachments } from "./useImageAttachments";
import { usePersistedState } from "./usePersistedState";
import { useRecentPages } from "./useRecentPages";
import { useRecentSearches } from "./useRecentSearches";
import { useResultsNavigation, type NavigableItem } from "./useResultsNavigation";

/* ================= TYPES ================= */

interface SearchProps {
  showSearch: boolean;
  onClose: () => void;
}

/* ================= MAIN COMPONENT ================= */

type Mode = "search" | "ai";

// Remembered across visits so the modal reopens exactly where the user left off.
const MODE_KEY = "search:mode";
const AI_DRAFT_KEY = "search:ai-draft";
const AI_THINKING_KEY = "search:ai-thinking";

const isMode = (value: unknown): value is Mode => value === "search" || value === "ai";
const isString = (value: unknown): value is string => typeof value === "string";
const isBoolean = (value: unknown): value is boolean => typeof value === "boolean";

const RESULT_LISTBOX_ID = "search-results-listbox";
const SEARCH_INPUT_ID = "search-input";

const Search = forwardRef<HTMLDivElement, SearchProps>(({ showSearch, onClose }, ref) => {
  const inputRef = useRef<HTMLInputElement>(null);
  // AI mode has its own multi-line input (pinned to the bottom, like a chat app).
  const aiInputRef = useRef<HTMLTextAreaElement>(null);
  const resultRefs = useRef<Map<string, HTMLLIElement>>(new Map());
  const router = useRouter();

  // Search query and the unsent Pia message are kept separately, so switching
  // modes doesn't carry text from one into the other.
  const [searchTerm, setSearchTerm] = useState("");
  const [aiDraft, setAiDraft] = usePersistedState(AI_DRAFT_KEY, "", isString);
  // "Thinking" on: each question makes two AI calls (topic lookup, then the answer).
  // Off: one call. Remembered across visits.
  const [aiThinking, setAiThinking] = usePersistedState(AI_THINKING_KEY, false, isBoolean);
  const [mode, setMode] = usePersistedState<Mode>(MODE_KEY, "search", isMode);
  const isAiMode = mode === "ai";
  const normalizedTerm = normalizeSearch(searchTerm);
  const debouncedSearch = normalizeSearch(useDebounce(searchTerm, 300));

  const { recentSearches, addRecentSearch, removeRecentSearch, clearRecentSearches } =
    useRecentSearches();
  const { recentPages, addRecentPage, removeRecentPage, clearRecentPages } = useRecentPages();
  const { favoritePages, favoritePaths, toggleFavorite } = useFavoritePages();

  // True while the user has typed enough to search but the debounce hasn't
  // caught up yet — drives the skeleton state instead of flashing empty results.
  const isPending = normalizedTerm.length >= SEARCH_LENGTH && normalizedTerm !== debouncedSearch;

  /* ---------- Focus and Prevent Scroll ---------- */

  useEffect(() => {
    if (showSearch) {
      document.body.style.overflow = "hidden";

      // Wait until the search panel is rendered before focusing.
      requestAnimationFrame(() => {
        inputRef.current?.focus();
      });
    } else {
      document.body.style.overflow = "";
      setSearchTerm("");
    }

    return () => {
      document.body.style.overflow = "";
    };
  }, [showSearch]);

  /* ---------- Search Index (generated from all remote course metadata) ---------- */

  const [searchIndex, setSearchIndex] = useState<FlatSearchEntry[]>([]);
  const [searchIndexState, setSearchIndexState] = useState<"loading" | "ready" | "error">(
    "loading",
  );

  useEffect(() => {
    let active = true;

    fetch("/search-data.json")
      .then(async (response) => {
        if (!response.ok) {
          throw new Error(`Search data request failed with status ${response.status}.`);
        }

        const payload: unknown = await response.json();
        if (
          !payload ||
          typeof payload !== "object" ||
          !Array.isArray((payload as { entries?: unknown }).entries)
        ) {
          throw new Error("Generated search data has an invalid format.");
        }

        return (payload as { entries: FlatSearchEntry[] }).entries;
      })
      .then((entries) => {
        if (active) {
          setSearchIndex(entries);
          setSearchIndexState("ready");
        }
      })
      .catch(() => {
        if (active) {
          setSearchIndexState("error");
        }
      });

    return () => {
      active = false;
    };
  }, []);

  // Build the search engine as soon as the data arrives, during idle time, so
  // the first keystroke doesn't freeze the input while the index is built.
  useEffect(() => {
    if (searchIndexState !== "ready") return;

    const build = () => warmSearchIndex(searchIndex);
    if (typeof window.requestIdleCallback === "function") {
      const handle = window.requestIdleCallback(build, { timeout: 2000 });
      return () => window.cancelIdleCallback(handle);
    }

    const timer = window.setTimeout(build, 0);
    return () => window.clearTimeout(timer);
  }, [searchIndex, searchIndexState]);

  const categories = useMemo(() => Object.keys(mainData as MainDataType), []);

  /* ---------- AI mode ---------- */

  const {
    turns: aiTurns,
    busy: aiChatBusy,
    ask: askAi,
    regenerate: regenerateAi,
    stop: stopAi,
    reset: resetAi,
  } = useAiChat(searchIndex);
  const aiBusy = isAiMode && aiChatBusy;

  const {
    images: attachedImages,
    error: attachError,
    addFiles,
    removeImage,
    clearImages,
  } = useImageAttachments();

  // Closing the modal keeps everything: the active mode, the search query, the
  // draft and the conversation (all restored after a reload too). Starting over
  // is explicit: "New chat", or clearing the search box.
  const switchMode = useCallback((next: Mode) => setMode(next), [setMode]);

  // The other input mounts when the mode changes, so focus it after the switch.
  useEffect(() => {
    if (!showSearch) return;
    const frame = requestAnimationFrame(() => {
      if (mode === "ai") {
        aiInputRef.current?.focus();
      } else {
        // Select the restored query so typing replaces it.
        inputRef.current?.focus();
        inputRef.current?.select();
      }
    });
    return () => cancelAnimationFrame(frame);
  }, [mode, showSearch]);

  // Images can be pasted anywhere in the modal while chatting with Pia.
  // Pasting plain text is left alone.
  useEffect(() => {
    if (!showSearch || !isAiMode) return;

    const onPaste = (e: ClipboardEvent) => {
      const files = Array.from(e.clipboardData?.files ?? []).filter((file) =>
        file.type.startsWith("image/"),
      );
      if (files.length === 0) return;
      e.preventDefault();
      void addFiles(files);
    };

    document.addEventListener("paste", onPaste);
    return () => document.removeEventListener("paste", onPaste);
  }, [showSearch, isAiMode, addFiles]);

  // Drag and drop images onto the modal. The depth counter stops the overlay
  // flickering as the pointer crosses child elements.
  const [isDraggingFile, setIsDraggingFile] = useState(false);
  const dragDepth = useRef(0);

  const hasFiles = (e: DragEvent<HTMLElement>) => e.dataTransfer.types.includes("Files");

  const dragHandlers = isAiMode
    ? {
        onDragEnter: (e: DragEvent<HTMLElement>) => {
          if (!hasFiles(e)) return;
          e.preventDefault();
          dragDepth.current += 1;
          setIsDraggingFile(true);
        },
        onDragOver: (e: DragEvent<HTMLElement>) => {
          if (hasFiles(e)) e.preventDefault(); // required for drop to fire
        },
        onDragLeave: (e: DragEvent<HTMLElement>) => {
          if (!hasFiles(e)) return;
          dragDepth.current = Math.max(0, dragDepth.current - 1);
          if (dragDepth.current === 0) setIsDraggingFile(false);
        },
        onDrop: (e: DragEvent<HTMLElement>) => {
          if (!hasFiles(e)) return;
          e.preventDefault();
          dragDepth.current = 0;
          setIsDraggingFile(false);
          void addFiles(Array.from(e.dataTransfer.files));
        },
      }
    : {};

  // Label for the shortcut hints; resolved after mount so server and client markup match.
  const [isMac, setIsMac] = useState(false);
  useEffect(() => {
    setIsMac(/Mac|iPhone|iPad/.test(navigator.userAgent));
  }, []);
  const modKey = isMac ? "\u2318" : "Ctrl";

  // Modal-wide shortcuts, active in both search and AI mode:
  //  - Cmd/Ctrl+I toggles AI mode
  //  - "/" or simply starting to type refocuses the input (it loses focus after asking Pia)
  //  - Escape closes the modal even when the input isn't focused
  useEffect(() => {
    if (!showSearch) return;

    const onKeyDown = (e: globalThis.KeyboardEvent) => {
      const input = isAiMode ? aiInputRef.current : inputRef.current;

      // The input has its own Escape handler, which doesn't fire once it's blurred.
      if (e.key === "Escape" && e.target !== input) {
        e.preventDefault();
        onClose();
        return;
      }

      if ((e.metaKey || e.ctrlKey) && !e.shiftKey && !e.altKey && e.code === "KeyI") {
        e.preventDefault();
        switchMode(isAiMode ? "search" : "ai");
        return;
      }

      // Type-to-focus. Never steal keys from a field the user is already typing in,
      // and leave Space/Enter/arrows alone so buttons and lists keep working.
      const target = e.target;
      const inField =
        target === input ||
        (target instanceof HTMLElement &&
          (target.isContentEditable || ["INPUT", "TEXTAREA", "SELECT"].includes(target.tagName)));
      if (!input || inField || e.metaKey || e.ctrlKey || e.altKey || e.isComposing) return;

      if (e.key === "/") {
        e.preventDefault(); // focus only; don't type the slash
        input.focus();
      } else if (e.key.length === 1 && e.key !== " ") {
        input.focus(); // the keystroke then lands in the input
      }
    };

    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [showSearch, isAiMode, switchMode, onClose]);

  // Feedback for a submission that can't go through, so it never fails silently
  // — whether that's Enter in the input, a starter chip, or "Ask Pia instead".
  const [aiHint, setAiHint] = useState<string | null>(null);
  useEffect(() => {
    setAiHint(null);
  }, [aiDraft, isAiMode]);

  // The one path every "ask Pia" trigger goes through (Enter, Send, starter
  // chips, "Ask Pia instead"), so they all get the same checks and the same
  // visible feedback on failure. Attached images are sent with the message.
  const submitAi = useCallback(
    (rawQuestion: string) => {
      const question = rawQuestion.trim();
      const hasImages = attachedImages.length > 0;

      if (aiChatBusy) {
        setAiHint(`${AI_NAME} is still answering. Press Stop to ask something new.`);
        return;
      }
      if (!hasImages && question.length < AI_MIN_QUESTION_LENGTH) {
        setAiHint(`Type at least ${AI_MIN_QUESTION_LENGTH} characters, then press Enter.`);
        return;
      }
      if (searchIndexState === "loading") {
        setAiHint("Still loading the course index. Try again in a moment.");
        return;
      }

      askAi(question, attachedImages, aiThinking);
      clearImages();
      // The message stays visible in the chat, so clear the field. Keep focus
      // for quick follow-ups on desktop; on touch devices drop it so the
      // keyboard closes and the answer gets the room.
      setAiDraft("");
      if (window.matchMedia("(pointer: coarse)").matches) aiInputRef.current?.blur();
    },
    [askAi, aiChatBusy, aiThinking, attachedImages, clearImages, searchIndexState, setAiDraft],
  );

  /* ---------- Ranked Results ---------- */

  const results = useMemo(() => {
    if (isAiMode || searchIndexState !== "ready") return [];
    return searchContent(searchIndex, debouncedSearch);
  }, [isAiMode, searchIndex, searchIndexState, debouncedSearch]);

  // "Did you mean": always offered when nothing matched; when results are
  // showing, only if the query contains a word the index doesn't know (a typo).
  const suggestions = useMemo(
    () =>
      !isAiMode && searchIndexState === "ready"
        ? suggestQueries(searchIndex, debouncedSearch, { misspelledOnly: results.length > 0 })
        : [],
    [isAiMode, searchIndex, searchIndexState, debouncedSearch, results.length],
  );
  /* ---------- Flatten for keyboard navigation ---------- */

  // The generated index contains one record per searchable course/topic page.
  // Each course contributes its own row *and* one row per visible topic
  // beneath it, in the same top-to-bottom order they're rendered, so arrow
  // keys walk through every visible item instead of jumping course-to-course.
  const flatItems: NavigableItem[] = useMemo(
    () =>
      results.flatMap((result) => {
        const courseId = `${result.category}-${result.name}`;

        if (result.link) {
          return [
            {
              id: courseId,
              path: result.link,
              external: true,
            },
          ];
        }

        const coursePath = result.firstTopicPath
          ? result.firstTopicPath
          : createRoute("learn", result.category, result.name);

        const courseItem: NavigableItem = { id: courseId, path: coursePath };

        const routeItems: NavigableItem[] = result.routes.map((route) => ({
          id: `${courseId}-${route.path}`,
          path: route.path,
        }));

        return [courseItem, ...routeItems];
      }),
    [results],
  );

  // Display metadata for every openable result, keyed by path. Topic rows are
  // added after course rows so that when a course's link points at its first
  // topic, the more specific topic title wins.
  const pageMeta = useMemo(() => {
    const map = new Map<string, SavedPage>();

    for (const result of results) {
      if (result.link) {
        map.set(result.link, {
          path: result.link,
          title: result.name,
          category: result.category,
          external: true,
        });
        continue;
      }

      const coursePath = result.firstTopicPath
        ? result.firstTopicPath
        : createRoute("learn", result.category, result.name);
      map.set(coursePath, { path: coursePath, title: result.name, category: result.category });

      for (const route of result.routes) {
        const routePath = route.path;
        map.set(routePath, {
          path: routePath,
          title: route.topic,
          category: result.category,
          course: result.name,
        });
      }
    }

    return map;
  }, [results]);

  // Remember both the query and the page it led to.
  const recordVisit = (path: string) => {
    addRecentSearch(searchTerm);

    const page = pageMeta.get(path);
    if (page) addRecentPage(page);
  };

  const openPage = (path: string, external?: boolean) => {
    if (external) {
      window.open(path, "_blank", "noopener,noreferrer");
    } else if (window.location.pathname.startsWith("/learn/") && path.startsWith("/learn/")) {
      // LearnRouteClient resolves whichever category is in the URL,
      // so a client-side pushState here
      // is safe even when the result belongs to a different category —
      // no full page reload needed. Only valid for /learn/ targets.
      pushClientPath(path);
    } else {
      // Anything outside /learn (e.g. /services, /contact) needs a real
      // Next.js navigation, otherwise the URL changes but nothing renders.
      router.push(path);
    }
    onClose();
  };

  const handleSelect = (path: string, external?: boolean) => {
    recordVisit(path);
    openPage(path, external);
  };

  const toggleFavoritePath = (path: string) => {
    const page = pageMeta.get(path);
    if (page) toggleFavorite(page);
  };

  // Re-opening a saved page also bumps it to the top of "Recently visited".
  // For a new-tab open the browser does the navigation, so only record it.
  const handleSavedPageSelect = (page: SavedPage, { newTab }: { newTab: boolean }) => {
    addRecentPage(page);
    if (!newTab) openPage(page.path, page.external);
  };

  // Click handlers for search-result anchors: plain click routes in-app,
  // Ctrl/Cmd/Shift-click and middle-click fall through to the browser.
  const resultLinkProps = (path: string) => ({
    onClick: (e: MouseEvent<HTMLAnchorElement>) => {
      if (isModifiedClick(e)) {
        recordVisit(path);
        return;
      }
      e.preventDefault();
      handleSelect(path);
    },
    onAuxClick: (e: MouseEvent<HTMLAnchorElement>) => {
      if (e.button === 1) recordVisit(path);
    },
  });

  const { activeId, handleKeyDown } = useResultsNavigation({
    items: flatItems,
    onSelect: handleSelect,
    onEscape: onClose,
  });

  // Keep the highlighted result scrolled into view as arrow keys move it
  useEffect(() => {
    if (!activeId) return;
    resultRefs.current.get(activeId)?.scrollIntoView({ block: "nearest" });
  }, [activeId]);

  const handleRecentSelect = (term: string) => {
    setSearchTerm(term);
    inputRef.current?.focus();
  };

  const handleScroll = () => {
    (isAiMode ? aiInputRef.current : inputRef.current)?.blur();
  };

  /* ================= RENDER ================= */

  return (
    <section
      className={`search-section ${showSearch ? "active" : ""}`}
      role="dialog"
      aria-modal="true"
      aria-label="Search"
      aria-hidden={!showSearch}
    >
      <div
        className={`search-container ${isAiMode ? "ai-active" : ""} ${aiBusy ? "ai-busy" : ""} ${
          isDraggingFile ? "ai-dragging" : ""
        }`}
        ref={ref}
        {...dragHandlers}
      >
        <div className="search-header">
          {isAiMode ? (
            <div className="ai-header-title">
              <AutoAwesomeIcon aria-hidden="true" />
              <span>{AI_NAME}</span>
              <span className="ai-assistant-badge">AI</span>
            </div>
          ) : (
            <SearchBar
              searchTerm={searchTerm}
              setSearchTerm={setSearchTerm}
              inputRef={inputRef}
              inputId={SEARCH_INPUT_ID}
              placeholder="Search..."
              onKeyDown={handleKeyDown}
              ariaControls={RESULT_LISTBOX_ID}
              ariaActiveDescendant={activeId}
              ariaExpanded={flatItems.length > 0}
            />
          )}
          {isAiMode && aiTurns.length > 0 && !aiChatBusy && (
            <button
              type="button"
              className="toggle-button ai-newchat"
              onClick={() => {
                resetAi();
                clearImages();
                aiInputRef.current?.focus();
              }}
              title="Start a new chat"
            >
              <AddCommentOutlinedIcon aria-hidden="true" />
              <span className="ai-toggle-label">New chat</span>
            </button>
          )}
          <button
            type="button"
            className={`toggle-button ai-toggle ${isAiMode ? "active" : ""}`}
            onClick={() => switchMode(isAiMode ? "search" : "ai")}
            aria-pressed={isAiMode}
            aria-label={isAiMode ? "Switch back to regular search" : `Ask ${AI_NAME}`}
            aria-keyshortcuts="Control+I Meta+I"
            title={`${isAiMode ? "Switch back to regular search" : `Ask ${AI_NAME}`} (${modKey}+I)`}
          >
            <AutoAwesomeIcon aria-hidden="true" />
            <span className="ai-toggle-label">{isAiMode ? "Search" : `Ask ${AI_NAME}`}</span>
          </button>
          <button
            type="button"
            className="toggle-button cancel"
            onClick={onClose}
            aria-label="Close search"
            title="Close search"
          >
            Close
          </button>
        </div>

        <div className="search-results" onTouchStart={handleScroll}>
          {!isAiMode && !isPending && results.length > 0 && suggestions.length > 0 && (
            <div className="did-you-mean" role="status">
              <span>Did you mean:</span>
              {suggestions.map(({ suggestion }) => (
                <button
                  key={suggestion}
                  type="button"
                  className="category-chip"
                  onMouseDown={(e) => e.preventDefault()}
                  onClick={() => setSearchTerm(suggestion)}
                >
                  {suggestion}
                </button>
              ))}
            </div>
          )}
          {isAiMode ? (
            <SearchAiPanel
              turns={aiTurns}
              hint={aiHint ?? attachError}
              suggestions={AI_STARTERS}
              onAsk={submitAi}
              favoritePaths={favoritePaths}
              onOpenSource={handleSavedPageSelect}
              onToggleFavorite={toggleFavorite}
              // Regenerate follows the current thinking switch, so a weak answer can be retried with it on.
              onRegenerate={() => regenerateAi(aiThinking)}
              active={showSearch}
            />
          ) : normalizedTerm.length < SEARCH_LENGTH ? (
            favoritePages.length > 0 || recentPages.length > 0 || recentSearches.length > 0 ? (
              <div className="recent-searches">
                {favoritePages.length > 0 && (
                  <section className="recent-section" aria-label="Favorite pages">
                    <div className="recent-header">
                      <h2 className="recent-title">Favorites</h2>
                    </div>
                    <ul className="recent-list">
                      {favoritePages.map((page) => (
                        <PageRow
                          key={page.path}
                          page={page}
                          isFavorite
                          onOpen={(opts) => handleSavedPageSelect(page, opts)}
                          onToggleFavorite={() => toggleFavorite(page)}
                        />
                      ))}
                    </ul>
                  </section>
                )}

                {recentPages.length > 0 && (
                  <section className="recent-section" aria-label="Recently visited pages">
                    <div className="recent-header">
                      <h2 className="recent-title">Recently visited</h2>
                      <button
                        type="button"
                        className="recent-clear"
                        onClick={clearRecentPages}
                        aria-label="Clear recently visited pages"
                      >
                        Clear all
                      </button>
                    </div>
                    <ul className="recent-list">
                      {recentPages.map((page) => (
                        <PageRow
                          key={page.path}
                          page={page}
                          isFavorite={favoritePaths.has(page.path)}
                          onOpen={(opts) => handleSavedPageSelect(page, opts)}
                          onToggleFavorite={() => toggleFavorite(page)}
                          onRemove={() => removeRecentPage(page.path)}
                        />
                      ))}
                    </ul>
                  </section>
                )}

                {recentSearches.length > 0 && (
                  <section className="recent-section" aria-label="Recent searches">
                    <div className="recent-header">
                      <h2 className="recent-title">Recent searches</h2>
                      <button
                        type="button"
                        className="recent-clear"
                        onClick={clearRecentSearches}
                        aria-label="Clear recent searches"
                      >
                        Clear all
                      </button>
                    </div>
                    <ul className="recent-list">
                      {recentSearches.map((term) => (
                        <li key={term} className="recent-item">
                          <button
                            type="button"
                            className="recent-select"
                            onClick={() => handleRecentSelect(term)}
                          >
                            <HistoryIcon fontSize="small" aria-hidden="true" />
                            <span className="recent-term">{term}</span>
                          </button>
                          <button
                            type="button"
                            className="recent-remove"
                            onClick={() => removeRecentSearch(term)}
                            aria-label={`Remove "${term}" from recent searches`}
                            title="Remove"
                          >
                            <CloseIcon fontSize="small" aria-hidden="true" />
                          </button>
                        </li>
                      ))}
                    </ul>
                  </section>
                )}
              </div>
            ) : (
              <div className="result-message">
                <p>
                  🔎 Please enter at least {SEARCH_LENGTH}{" "}
                  {SEARCH_LENGTH === 1 ? "character" : "characters"} to search.
                </p>
              </div>
            )
          ) : searchIndexState === "loading" ? (
            <div className="result-message">
              <p aria-live="polite">Loading search data...</p>
            </div>
          ) : searchIndexState === "error" ? (
            <div className="result-message result-empty">
              <p role="alert">Search data is temporarily unavailable.</p>
            </div>
          ) : isPending ? (
            <ul className="result-skeleton" aria-hidden="true">
              {[0, 1, 2].map((i) => (
                <li key={i} className="skeleton-card">
                  <div className="skeleton-line skeleton-title" />
                  <div className="skeleton-line skeleton-row" />
                  <div className="skeleton-line skeleton-row short" />
                </li>
              ))}
            </ul>
          ) : results.length > 0 ? (
            <ul
              className="result-container"
              id={RESULT_LISTBOX_ID}
              role="listbox"
              aria-label="Search results"
            >
              {results.map((result) => {
                const id = `${result.category}-${result.name}`;

                const coursePath = result.link
                  ? result.link
                  : (result.firstTopicPath ?? createRoute("learn", result.category, result.name));

                return (
                  <li
                    className={`result-card ${activeId === id ? "active" : ""}`}
                    key={id}
                    id={id}
                    role="option"
                    aria-selected={activeId === id}
                    ref={(el) => {
                      if (el) resultRefs.current.set(id, el);
                      else resultRefs.current.delete(id);
                    }}
                  >
                    <p className="result-breadcrumb">
                      <span>{result.category}</span>
                      <span className="breadcrumb-sep" aria-hidden="true">
                        /
                      </span>
                    </p>
                    <div className="result-title-row">
                      <h3>
                        {result.link ? (
                          <a
                            href={coursePath}
                            target="_blank"
                            rel="noopener noreferrer"
                            onClick={() => recordVisit(coursePath)}
                          >
                            <HighlightMatch text={result.name} query={debouncedSearch} />{" "}
                            <OpenInNewIcon
                              className="arrow-icon"
                              fontSize="small"
                              aria-hidden="true"
                            />
                          </a>
                        ) : (
                          <a href={coursePath} {...resultLinkProps(coursePath)}>
                            <HighlightMatch text={result.name} query={debouncedSearch} />{" "}
                            <ArrowForwardIcon
                              className="arrow-icon"
                              fontSize="small"
                              aria-hidden="true"
                            />
                          </a>
                        )}
                      </h3>
                      <FavoriteToggle
                        isFavorite={favoritePaths.has(coursePath)}
                        title={result.name}
                        onToggle={() => toggleFavoritePath(coursePath)}
                      />
                    </div>

                    {/* Remote topics are intentionally loaded only after opening a course. */}
                    {!result.link && result.routes.length > 0 && (
                      <ul className="result-route-list">
                        {result.routes.map((route) => {
                          const routeId = `${result.category}-${result.name}-${route.path}`;
                          const routePath = route.path;

                          return (
                            <li
                              key={routeId}
                              id={routeId}
                              role="option"
                              aria-selected={activeId === routeId}
                              className={`result-route ${activeId === routeId ? "active" : ""}`}
                              ref={(el) => {
                                if (el) resultRefs.current.set(routeId, el);
                                else resultRefs.current.delete(routeId);
                              }}
                            >
                              <a href={routePath} {...resultLinkProps(routePath)}>
                                <HighlightMatch text={route.topic} query={debouncedSearch} />
                              </a>
                              <FavoriteToggle
                                isFavorite={favoritePaths.has(routePath)}
                                title={route.topic}
                                onToggle={() => toggleFavoritePath(routePath)}
                              />
                            </li>
                          );
                        })}
                      </ul>
                    )}
                  </li>
                );
              })}
            </ul>
          ) : (
            <div className="result-message result-empty">
              <p>
                No results found for <strong>{searchTerm}</strong>.
              </p>

              <button
                type="button"
                className="category-chip ai-fallback"
                onClick={() => {
                  setMode("ai");
                  submitAi(searchTerm);
                }}
              >
                <AutoAwesomeIcon fontSize="inherit" aria-hidden="true" />
                Ask {AI_NAME} instead
              </button>

              {suggestions.length > 0 && (
                <div className="empty-state-suggestions-query">
                  <span>Did you mean:</span>{" "}
                  <div className="category-chip-list">
                    {suggestions.map(({ suggestion }) => (
                      <button
                        key={suggestion}
                        type="button"
                        className="category-chip"
                        onClick={() => setSearchTerm(suggestion)}
                      >
                        {suggestion}
                      </button>
                    ))}
                  </div>
                </div>
              )}

              <ul className="empty-state-suggestions">
                <li>Double-check the spelling</li>
                <li>Try a shorter or more search keyword</li>
              </ul>
              {categories.length > 0 && (
                <div className="empty-state-categories">
                  <span>Or browse a category:</span>{" "}
                  <div className="category-chip-list">
                    {categories.map((category) => (
                      <button
                        key={category}
                        type="button"
                        className="category-chip"
                        onClick={() => setSearchTerm(category)}
                      >
                        {toTitleCase(category)}
                      </button>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}
        </div>

        {isAiMode && (
          <SearchAiInput
            value={aiDraft}
            placeholder={
              aiTurns.length > 0 ? `Ask ${AI_NAME} a follow-up...` : `Ask ${AI_NAME} a question...`
            }
            inputRef={aiInputRef}
            images={attachedImages}
            busy={aiChatBusy}
            canSend={aiDraft.trim().length >= AI_MIN_QUESTION_LENGTH || attachedImages.length > 0}
            thinking={aiThinking}
            onToggleThinking={() => setAiThinking((on) => !on)}
            onChange={setAiDraft}
            onSend={() => submitAi(aiDraft)}
            onStop={stopAi}
            onEscape={onClose}
            onPickFiles={(files) => void addFiles(files)}
            onRemoveImage={removeImage}
          />
        )}

        <footer className="search-shortcuts" aria-hidden="true">
          <div className="shortcut-group">
            <span className="shortcut-key">
              <KeyboardReturnIcon fontSize="inherit" />
            </span>
            <span>{isAiMode ? "Send" : "Select"}</span>
          </div>

          {!isAiMode && (
            <div className="shortcut-group">
              <span className="shortcut-key">
                <KeyboardArrowUpIcon fontSize="inherit" />
              </span>

              <span className="shortcut-key">
                <KeyboardArrowDownIcon fontSize="inherit" />
              </span>

              <span>Navigate</span>
            </div>
          )}

          <div className="shortcut-group">
            <span className="shortcut-key shortcut-text">{modKey}</span>
            <span className="shortcut-key shortcut-text">I</span>
            <span>{isAiMode ? "Search" : `Ask ${AI_NAME}`}</span>
          </div>

          <div className="shortcut-group">
            <span className="shortcut-key shortcut-text">/</span>
            <span>Focus</span>
          </div>

          <div className="shortcut-group">
            <span className="shortcut-key shortcut-text">Esc</span>
            <span>Close</span>
          </div>
        </footer>
      </div>
    </section>
  );
});

Search.displayName = "Search";

export default Search;
