"use client";

import { useCallback, useMemo } from "react";
import { getPageId, isSavedPage, type SavedPage } from "./savedPage";
import { useStoredList } from "./useStoredList";

export const FAVORITE_PAGES_KEY = "search:favorites";
// Deliberately generous: unlike "recent" lists, favorites are curated by the
// user, so silently dropping the oldest one would lose something they chose to keep.
export const MAX_FAVORITE_PAGES = 50;

/** Persists pages the user starred, newest favorite first, de-duplicated by path. */
export function useFavoritePages() {
  const { items, add, remove } = useStoredList<SavedPage>({
    key: FAVORITE_PAGES_KEY,
    max: MAX_FAVORITE_PAGES,
    isValid: isSavedPage,
    getId: getPageId,
  });

  const favoritePaths = useMemo(() => new Set(items.map(getPageId)), [items]);

  const toggleFavorite = useCallback(
    (page: SavedPage) => {
      if (favoritePaths.has(page.path)) remove(page.path);
      else add(page);
    },
    [favoritePaths, add, remove],
  );

  return { favoritePages: items, favoritePaths, toggleFavorite };
}
