"use client";

import { useCallback, useEffect, useRef, useState } from "react";

export interface StoredListOptions<T> {
  /** localStorage key. */
  key: string;
  /** Maximum number of items kept (oldest are dropped first). */
  max: number;
  /** Type guard used to discard malformed / tampered entries when reading. */
  isValid: (value: unknown) => value is T;
  /** Identity used for de-duplication and removal. */
  getId: (item: T) => string;
}

/**
 * A small localStorage-backed "most recent first" list.
 *
 * - De-duplicates by `getId`, moving a repeated item back to the top.
 * - SSR-safe: starts empty and hydrates after mount, so markup always matches.
 * - Never throws (blocked storage, quota errors, corrupted JSON).
 * - Syncs across browser tabs via the `storage` event.
 *
 * `isValid` and `getId` should be stable references (module-level functions).
 */
export function useStoredList<T>({ key, max, isValid, getId }: StoredListOptions<T>) {
  const [items, setItems] = useState<T[]>([]);
  // Mirror of the latest list so callbacks stay stable and never read stale state.
  const listRef = useRef<T[]>([]);

  const read = useCallback((): T[] => {
    try {
      const raw = window.localStorage.getItem(key);
      if (!raw) return [];

      const parsed: unknown = JSON.parse(raw);
      if (!Array.isArray(parsed)) return [];

      return parsed.filter(isValid).slice(0, max);
    } catch {
      return [];
    }
  }, [key, max, isValid]);

  const commit = useCallback(
    (next: T[]) => {
      listRef.current = next;
      setItems(next);

      try {
        if (next.length === 0) window.localStorage.removeItem(key);
        else window.localStorage.setItem(key, JSON.stringify(next));
      } catch {
        // Storage full or unavailable — this is a convenience feature, so fail silently.
      }
    },
    [key],
  );

  useEffect(() => {
    const initial = read();
    listRef.current = initial;
    setItems(initial);

    const onStorage = (event: StorageEvent) => {
      // `event.key === null` means the whole storage was cleared.
      if (event.key !== null && event.key !== key) return;
      const synced = read();
      listRef.current = synced;
      setItems(synced);
    };

    window.addEventListener("storage", onStorage);
    return () => window.removeEventListener("storage", onStorage);
  }, [key, read]);

  const add = useCallback(
    (item: T) => {
      const id = getId(item);
      const rest = listRef.current.filter((existing) => getId(existing) !== id);
      commit([item, ...rest].slice(0, max));
    },
    [commit, getId, max],
  );

  const remove = useCallback(
    (id: string) => commit(listRef.current.filter((existing) => getId(existing) !== id)),
    [commit, getId],
  );

  const clear = useCallback(() => commit([]), [commit]);

  return { items, add, remove, clear };
}
