"use client";
import AutoAwesomeIcon from "@mui/icons-material/AutoAwesome";
import ClearAllIcon from "@mui/icons-material/ClearAll";
import CloseIcon from "@mui/icons-material/Close";
import MenuIcon from "@mui/icons-material/MoreHoriz";
import ShareIcon from "@mui/icons-material/Share";
import { usePathname } from "next/navigation";
import { useEffect, useRef, useState } from "react";
import ThemeSwitcher from "~/theme/ThemeSwitcher";
import SyntaxThemeSwitcher from "~/ui/Syntax/SyntaxThemeSwitcher";
import { SITE_NAME } from "~/utils/domain";
import Backdrop from "../Backdrop/Backdrop";
import Search from "../Search/Search";
import "./Header.css";
import NavLink from "./NavLink";

interface HeaderProps {
  onClick?: () => void;
  isShowTopicButton?: boolean;
  float?: boolean;
}

// Nav is kept intentionally simple: Learn | Products | Services | About | Contact.
// Learn already covers exploration/discovery, so there is no separate
// "Explore" item — and no items beyond the four core sections of the brand.
const NAV_LINKS = [
  { to: "/learn", label: "Learn", end: false },
  { to: "/products", label: "Products", end: false },
  { to: "/services", label: "Services", end: false },
  { to: "/work", label: "Work", end: false },
  { to: "/about", label: "About", end: false },
  { to: "/contact", label: "Contact", end: false },
];

const Header: React.FC<HeaderProps> = ({ onClick, isShowTopicButton = false, float = false }) => {
  const [showMobileMenu, setShowMobileMenu] = useState(false);
  const [showSearch, setShowSearch] = useState(false);
  const mobileMenuRef = useRef<HTMLDivElement>(null);
  const searchRef = useRef<HTMLDivElement>(null);

  const pathname = usePathname() ?? "/";

  useEffect(() => {
    if (pathname === "/work" || pathname.startsWith("/work/")) return;
    if (pathname === "/learn" || pathname.startsWith("/learn/")) return;
    window.scrollTo({ top: 0, behavior: "smooth" });
  }, [pathname]);

  useEffect(() => {
    if (showMobileMenu || showSearch) return;

    // Defer the state update so route changes do not trigger a cascading
    // render from inside the effect body.
    const closeMenu = window.setTimeout(() => setShowMobileMenu(false), 0);
    return () => window.clearTimeout(closeMenu);
  }, [pathname, showMobileMenu, showSearch]);

  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth > 1100) {
        setShowMobileMenu(false);
      }
    };

    window.addEventListener("resize", handleResize);

    return () => {
      window.removeEventListener("resize", handleResize);
    };
  }, []);

  useEffect(() => {
    function handleClickOutside(event: MouseEvent | TouchEvent) {
      if (
        showMobileMenu &&
        mobileMenuRef.current &&
        !mobileMenuRef.current.contains(event.target as Node)
      ) {
        setShowMobileMenu(false);
      }
      if (showSearch && searchRef.current && !searchRef.current.contains(event.target as Node)) {
        setShowSearch(false);
      }
    }

    document.addEventListener("mousedown", handleClickOutside);
    document.addEventListener("touchstart", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
      document.removeEventListener("touchstart", handleClickOutside);
    };
  }, [showMobileMenu, showSearch]);

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "k") {
        event.preventDefault();
        setShowSearch(true);
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, []);

  const handleShare = async () => {
    const url = new URL(window.location.href);

    // Remove the hash fragment (#...)
    url.hash = "";

    const shareUrl = url.toString();

    try {
      if (navigator.share) {
        await navigator.share({
          title: document.title,
          url: shareUrl,
        });
      } else {
        await navigator.clipboard.writeText(shareUrl);
        alert("Link copied to clipboard!");
      }
    } catch {
      // User cancelled or sharing failed
    }
  };

  return (
    <div className={`header-container ${float ? "float" : "normal"}`}>
      <header className={`header ${float ? "float" : "normal"} app-header`}>
        <div className="menu-logo">
          {isShowTopicButton && (
            <button
              type="button"
              className="toggle-button toggle-button-wh logo-toggle"
              onClick={onClick}
              aria-label="Toggle topics"
              title="Toggle topics"
            >
              <ClearAllIcon aria-hidden="true" />
            </button>
          )}
          <NavLink to="/" className="logo">
            {SITE_NAME}
          </NavLink>
        </div>

        <nav className="header-nav" aria-label="Main navigation">
          <ul className={`nav-links ${isShowTopicButton ? "has-toggle" : "no-toggle"}`}>
            {isShowTopicButton && (
              <li>
                <button
                  type="button"
                  className="toggle-button toggle-button-wh nav-toggle"
                  onClick={onClick}
                  aria-label="Toggle topics"
                  title="Toggle topics"
                >
                  <ClearAllIcon aria-hidden="true" />
                </button>
              </li>
            )}

            {/* Desktop nav */}
            {NAV_LINKS.map(({ to, label, end }, index) => (
              <li key={to} className={`header-nav-item ${index == 0 ? "nav-space" : ""}`}>
                <NavLink to={to} end={end} className={({ isActive }) => (isActive ? "active" : "")}>
                  {label}
                </NavLink>
              </li>
            ))}

            {/* Right side icons */}
            <li className="header-actions">
              <button
                type="button"
                className="toggle-button toggle-button-wh"
                onClick={handleShare}
                aria-label="Share this page"
                title="Share this page"
              >
                <ShareIcon aria-hidden="true" />
              </button>

              {/* Search + AI assistant (Pia). Styled in Header.css; the orb comes from Search.css. */}
              <button
                type="button"
                className="toggle-button toggle-button-h search-toggle"
                onClick={() => setShowSearch(true)}
                aria-label="Search or ask Pia"
                title="Search or ask Pia (Ctrl+K)"
                aria-keyshortcuts="Control+K"
              >
                <span className="pia-orb sm" aria-hidden="true">
                  <AutoAwesomeIcon className="pia-orb-icon" />
                </span>
                <span className="search-toggle-label">Search or ask Pia</span>
                <span className="search-shortcut" aria-hidden="true">
                  <span className="shortcut-key-search">Ctrl</span>
                  <span className="shortcut-key-search">K</span>
                </span>
              </button>

              {pathname.startsWith("/learn") && <SyntaxThemeSwitcher />}

              <ThemeSwitcher variant="circle" />

              <button
                type="button"
                className="toggle-button toggle-button-wh header-mobile-menu"
                onClick={() => setShowMobileMenu((v) => !v)}
                aria-label={showMobileMenu ? "Close menu" : "Open menu"}
                title="Menu"
                aria-expanded={showMobileMenu}
                aria-controls="mobile-menu"
              >
                <MenuIcon aria-hidden="true" />
              </button>
            </li>
          </ul>
        </nav>
      </header>

      <Search showSearch={showSearch} ref={searchRef} onClose={() => setShowSearch(false)} />

      <Backdrop enable={showMobileMenu} />

      {/* Mobile off-canvas menu */}
      <div
        id="mobile-menu"
        className={`off-canvas-glass ${showMobileMenu ? "active" : ""}`}
        ref={mobileMenuRef}
        aria-hidden={!showMobileMenu}
      >
        <div className="off-canvas-header">
          <h3>Menu</h3>
          <button
            type="button"
            onClick={() => setShowMobileMenu(false)}
            aria-label="Close menu"
            title="Close menu"
          >
            <CloseIcon aria-hidden="true" />
          </button>
        </div>
        <nav className="off-canvas-nav" aria-label="Mobile navigation">
          <ul className="off-canvas-list">
            {NAV_LINKS.map(({ to, label, end }) => (
              <li key={to}>
                <NavLink to={to} end={end} onClick={() => setShowMobileMenu(false)}>
                  {label}
                </NavLink>
              </li>
            ))}
          </ul>
        </nav>
      </div>
    </div>
  );
};

export default Header;