"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { type AnchorHTMLAttributes, type ReactNode } from "react";

type ClassNameProp = string | ((props: { isActive: boolean }) => string);

interface NavLinkProps extends Omit<
  AnchorHTMLAttributes<HTMLAnchorElement>,
  "href" | "className" | "children"
> {
  to: string;
  end?: boolean;
  className?: ClassNameProp;
  children?: ReactNode | ((props: { isActive: boolean }) => ReactNode);
}

function normalize(path: string) {
  const clean = path.split("?")[0].split("#")[0];
  return clean !== "/" ? clean.replace(/\/+$/, "") : "/";
}

function isPathActive(pathname: string, to: string, end?: boolean) {
  const current = normalize(pathname);
  const target = normalize(to);

  if (target === "/") {
    return current === "/";
  }

  if (end) {
    return current === target;
  }

  return current === target || current.startsWith(`${target}/`);
}

export default function NavLink({ to, end, className, children, ...rest }: NavLinkProps) {
  const pathname = usePathname() ?? "";
  const isExternal = /^https?:\/\//.test(to);

  const isActive = !isExternal && isPathActive(pathname, to, end);

  const resolvedClassName =
    typeof className === "function"
      ? className({ isActive })
      : [className, isActive && "active"].filter(Boolean).join(" ");

  return (
    <Link
      href={to}
      className={resolvedClassName || undefined}
      aria-current={isActive ? "page" : undefined}
      target={isExternal ? "_blank" : undefined}
      rel={isExternal ? "noopener noreferrer" : undefined}
      {...rest}

    >
      {typeof children === "function" ? children({ isActive }) : children}
    </Link>
  );
}
