import MiniSearch, {
  type SearchResult as MiniSearchHit,
  type Options as MiniSearchOptions,
} from "minisearch";
import { stemmer } from "stemmer";
import type { GeneratedSearchEntry } from "~/features/learning/data/remote-index";
import type { MainDataType } from "~/model/main_data_model";
import { normalizeSearch } from "~/utils/custom_string";
import SYNONYM_GROUPS from "./SYNONYM_GROUPS";
import { SEARCH_LENGTH } from "./const";

/* ================================ TYPES ================================ */

export type FlatSearchEntry = GeneratedSearchEntry;

export interface SearchRouteMatch {
  topic: string;
  path: string;
  score: number;
}

export interface SearchResult {
  category: string;
  name: string;
  routes: SearchRouteMatch[];
  score: number;
  /** First topic of the course, used to deep-link the course-level result. */
  firstTopic?: string;
  firstTopicPath?: string;
  /** Set when the course is an external link rather than in-app topics. */
  link?: string;
}

/* ============================ SYNCHRONOUS INDEX BUILDER ============================ */

/**
 * Keeps a synchronous local index builder for callers and tests that need it.
 * The application search UI uses public/search-data.json, generated from all
 * configured remote course metadata during the build.
 */
export function buildSearchIndex(source: MainDataType): FlatSearchEntry[] {
  const index: FlatSearchEntry[] = [];
  let id = 0;

  Object.entries(source).forEach(([category, courses]) => {
    const registryCourses = Array.isArray(courses)
      ? courses.map((course) => course.about)
      : Object.values(courses);

    registryCourses.forEach((course) => {
      index.push({
        id: String(id++),
        category,
        name: course.name,
        description: course.description,
        link: course.link,
        path: course.link ?? `/learn/${category}/${course.name}`,
      });
    });
  });

  return index;
}

/* ============================== MINISEARCH =============================== */

/**
 * MiniSearch is a production-grade, in-memory full-text search library used
 * by real-world documentation tooling. It's a good fit here because it
 * offers, out of the box, everything the previous hand-rolled ranking tried
 * to reimplement:
 *
 * - `fields` + `searchOptions.boost` gives per-field relevance priority —
 *   a `topic` hit outranks a `name` hit, which outranks a `category` hit —
 *   without any manual scoring math.
 * - `fuzzy` gives typo tolerance (edit-distance based) on every search, not
 *   as a separate fallback pass. It's scaled to term length below, which is
 *   how real search engines avoid over-fuzzing short words: a 1-character
 *   edit on a 3-letter word changes its meaning, but on a 9-letter word
 *   it's almost certainly a typo.
 * - `prefix` gives "starts with" / incremental-typing matches, which is
 *   exactly how documentation search boxes are expected to behave.
 * - `combineWith: "AND"` requires every term in a multi-word query to match
 *   *something* (fuzzily or as a prefix), which is what people expect from
 *   a real search engine — "raect hoosk" should still find "React Hooks".
 * - `processTerm` runs every indexed and queried term through the same
 *   `normalizeSearch` used elsewhere in the app, so index-time and
 *   query-time normalization (case, accents, punctuation) never drift
 *   apart — a common source of "why doesn't this match" bugs.
 * - MiniSearch builds and holds a single in-memory index (an inverted
 *   index over terms, not a per-query linear scan), so it scales to large,
 *   effectively unlimited record counts — the same design real doc sites
 *   rely on for instant search-as-you-type.
 *
 * On top of MiniSearch's own scoring, `boostDocument` below adds an exact-
 * match preference: a document whose topic/name/category is *exactly* the
 * searched term (e.g. topic "c" for query "c") is boosted well above a
 * document that merely contains the term as a prefix (e.g. "css"). Without
 * this, a short query like "c" can rank "css" above the literal "c" topic,
 * because MiniSearch's built-in prefix discount alone isn't steep enough
 * once field boosts and term frequency come into play.
 */

/* ============================== TOKENIZING ============================== */

// Same separator set MiniSearch uses by default (whitespace + punctuation).
const SEPARATORS = /[\n\r\p{Z}\p{P}]+/u;
// Boundaries inside identifiers: "toUpperCase" -> to|Upper|Case,
// "JSONParser" -> JSON|Parser. Digits are not boundaries, so "es6"/"h1" stay whole.
const CAMEL_BOUNDARY = /([\p{Ll}\p{N}])(\p{Lu})|(\p{Lu}+)(\p{Lu}\p{Ll})/gu;
// Joined forms ("uppercase") are only worth their index cost on short,
// title-like fields. Long prose (description) just gets split into words.
const JOIN_FIELDS = new Set(["topic", "name", "category", "keywords"]);
const MAX_JOIN_PARTS = 4;
const SEARCH_FIELDS = ["topic", "name", "category", "description", "keywords"];

/** Splits text into words, breaking camelCase / PascalCase identifiers apart. */
function splitWords(text: string): string[] {
  return text
    .split(SEPARATORS)
    .filter(Boolean)
    .flatMap((word) => word.replace(CAMEL_BOUNDARY, "$1$3 $2$4").split(" "))
    .filter(Boolean);
}

/**
 * Query-side tokenizer: just the words, so "toUpperCase", "upper case" and
 * "upper" all produce terms that exist in the index.
 */
function tokenizeQuery(text: string): string[] {
  return splitWords(text);
}

/**
 * Index-side tokenizer. MiniSearch only matches terms from their *start*, so
 * an identifier indexed as the single word "touppercase" could never be found
 * by "upper", "case" or "uppercase". For every whitespace-delimited chunk we
 * therefore index each part ("to", "upper", "case") plus every run of
 * adjacent parts joined together ("touppercase", "uppercase", "toupper").
 * Plain words produce exactly one token, so normal prose is unaffected.
 */
function tokenizeIndex(text: string, fieldName?: string): string[] {
  const tokens: string[] = [];
  const joinParts = fieldName !== undefined && JOIN_FIELDS.has(fieldName);

  for (const chunk of text.split(/[\n\r\p{Z}]+/u)) {
    const parts = splitWords(chunk);
    if (parts.length === 0) continue;

    tokens.push(...parts);
    if (!joinParts || parts.length < 2) continue;

    const limit = Math.min(parts.length, MAX_JOIN_PARTS);
    for (let start = 0; start < limit; start++) {
      for (let end = start + 2; end <= limit; end++) {
        tokens.push(parts.slice(start, end).join(""));
      }
    }
    // The full identifier, even when it has more than MAX_JOIN_PARTS parts.
    if (parts.length > MAX_JOIN_PARTS) tokens.push(parts.join(""));
  }

  return tokens;
}

/** Reads a field as plain text (arrays are joined). */
function fieldText(doc: FlatSearchEntry, field: string): string {
  const value = (doc as unknown as Record<string, unknown>)[field];
  return Array.isArray(value) ? value.join(" ") : typeof value === "string" ? value : "";
}

function processTerm(term: string): string | null {
  const normalized = normalizeSearch(term);
  if (!normalized) return null;
  return stemmer(normalized);
}

/**
 * Returns a multiplier applied to a document's score for a given searched
 * term, based on whether one of its stored fields is an exact word match
 * (not just a prefix/fuzzy hit) for that term. `term` is already
 * normalized+stemmed by MiniSearch before this is called, so each field's
 * words are run through the same `processTerm` before comparing.
 *
 * Topic gets the strongest boost since it's the most specific field;
 * name and category taper off from there. Any non-exact match (prefix or
 * fuzzy) falls through to the default multiplier of 1.
 */
function exactFieldBoost(term: string, storedFields?: Record<string, unknown>): number {
  if (!storedFields) return 1;

  const hasExactWord = (field: string) => {
    const value = storedFields[field];
    return (
      typeof value === "string" &&
      tokenizeIndex(value, field).some((word) => processTerm(word) === term)
    );
  };

  if (hasExactWord("topic")) return 8;
  if (hasExactWord("name")) return 5;
  if (hasExactWord("category")) return 3;

  return 1;
}

const SEARCH_OPTIONS = {
  boost: { topic: 3, name: 2, category: 1 },
  boostDocument: (_id: string, term: string, storedFields?: Record<string, unknown>) =>
    exactFieldBoost(term, storedFields),
  // Typo tolerance scales with term length. Terms are stemmed before the
  // lookup ("documentation" -> "document"), so a typo can sit several edits
  // from the stored form; capping this at 2 breaks real typos like
  // "documentaton", so the generous ratio stays.
  fuzzy: (term: string) => {
    const length = term.trim().length;

    return Math.min(0.4, Math.max(0.1, length / 20));
  },
  prefix: true,
  tokenize: tokenizeQuery,
  // Explicitly discount non-exact match types so a prefix/fuzzy hit can
  // never outweigh a true exact match, even before boostDocument's
  // multiplier is applied on top.
  weights: { fuzzy: 0.2, prefix: 0.35 },
  combineWith: "AND" as const,
};

const MINISEARCH_OPTIONS: MiniSearchOptions<FlatSearchEntry> = {
  idField: "id",
  fields: SEARCH_FIELDS,
  storeFields: [
    "category",
    "name",
    "topic",
    "firstTopic",
    "firstTopicPath",
    "link",
    "description",
    "path",
  ],
  tokenize: tokenizeIndex,
  processTerm,
  searchOptions: SEARCH_OPTIONS,
};

// One MiniSearch instance per index array, so repeated searches against the
// same (unchanged) index don't pay to rebuild the inverted index on every
// keystroke. Index arrays are typically built once per data source and
// reused, so this keeps searches cheap without any manual invalidation.
const engineCache = new WeakMap<FlatSearchEntry[], MiniSearch<FlatSearchEntry>>();

function getEngine(index: FlatSearchEntry[]): MiniSearch<FlatSearchEntry> {
  let engine = engineCache.get(index);
  if (!engine) {
    engine = new MiniSearch<FlatSearchEntry>(MINISEARCH_OPTIONS);
    engine.addAll(index);
    engineCache.set(index, engine);
  }
  return engine;
}
/**
 * MiniSearch reports suggestions in *processed* form (lowercased and stemmed:
 * "categories" -> "categori"), which would be shown to the user as-is. This
 * maps each stem back to a real word from the index. Built lazily, only the
 * first time a search comes back empty, and cached per index array.
 */
const surfaceCache = new WeakMap<FlatSearchEntry[], Map<string, string>>();

function getSurfaceForms(index: FlatSearchEntry[]): Map<string, string> {
  let forms = surfaceCache.get(index);
  if (forms) return forms;

  forms = new Map<string, string>();
  for (const entry of index) {
    for (const field of SEARCH_FIELDS) {
      const text = fieldText(entry, field);
      if (!text) continue;

      for (const word of splitWords(text)) {
        const stem = processTerm(word);
        if (stem && !forms.has(stem)) forms.set(stem, normalizeSearch(word));
      }
    }
  }

  surfaceCache.set(index, forms);
  return forms;
}

/**
 * Builds the search index ahead of time. The first search otherwise pays for
 * it on the keystroke; call this once the index data has loaded (e.g. from an
 * idle callback) so typing never blocks. Safe to call repeatedly.
 */
export function warmSearchIndex(index: FlatSearchEntry[]): void {
  if (index.length > 0) getEngine(index);
}

/* ============================== SYNONYMS =============================== */

// Declare each equivalence group once; both directions are derived below.
// Add your own domain terms here (framework nicknames, abbreviations, etc).

const SYNONYM_MAP: Map<string, string[]> = (() => {
  const map = new Map<string, string[]>();
  for (const group of SYNONYM_GROUPS) {
    const normalized = group.map((term) => normalizeSearch(term)).filter(Boolean);
    for (const term of normalized) {
      const existing = map.get(term) ?? [];
      const additions = normalized.filter((t) => t !== term && !existing.includes(t));
      map.set(term, [...existing, ...additions]);
    }
  }
  return map;
})();

const MAX_SYNONYM_WORDS = 3;
// Safety cap so a pathological query can't fan out into dozens of searches.
const MAX_QUERY_VARIANTS = 12;

/**
 * Builds query variants by substituting each word with its synonyms, one
 * word at a time — not a full cartesian product, so a two-synonym query
 * doesn't explode into a huge search fan-out. Each variant is searched
 * separately and results are merged by max score in `searchContent`,
 * which keeps `combineWith: "AND"` semantics intact per variant (every
 * *word* in that variant must still match something) while still letting
 * "js hooks" find content indexed as "javascript hooks".
 */
function generateQueryVariants(query: string): string[] {
  const words = query.split(/\s+/).filter(Boolean);
  if (words.length === 0) return [query];

  const variants = new Set<string>([query]);

  // Try every run of 1..MAX_SYNONYM_WORDS adjacent words as a phrase, so
  // multi-word groups like "react router" fire as well as single words.
  for (let start = 0; start < words.length; start++) {
    for (let size = 1; size <= MAX_SYNONYM_WORDS && start + size <= words.length; size++) {
      const synonyms = SYNONYM_MAP.get(words.slice(start, start + size).join(" "));
      if (!synonyms) continue;

      synonyms.forEach((synonym) => {
        variants.add([...words.slice(0, start), synonym, ...words.slice(start + size)].join(" "));
      });
    }
  }

  return Array.from(variants).slice(0, MAX_QUERY_VARIANTS);
}

/* ============================== AUTOSUGGEST ============================== */

/**
 * Suggestions are only shown when a search found nothing, and autoSuggest
 * runs the same matching as search, so with the normal options it would find
 * nothing too ("raect" is two edits from "react"). These looser options are
 * used for suggestions only: more typo tolerance, and any word may match so
 * "raect hoosk" still suggests "react hooks" and a stray word can't veto it.
 */
const SUGGEST_OPTIONS = {
  ...SEARCH_OPTIONS,
  fuzzy: (term: string) => (term.trim().length <= 3 ? 0 : 0.4),
  combineWith: "OR" as const,
};

export interface SearchSuggestion {
  suggestion: string;
  score: number;
}

export interface SuggestOptions {
  /** Maximum number of suggestions returned. Defaults to 5. */
  limit?: number;
  /**
   * Only suggest when at least one typed word is missing from the index
   * (neither a known word nor the start of one). Use this when results are
   * already on screen, so a correct query like "docs" doesn't get a
   * pointless "did you mean" next to it.
   */
  misspelledOnly?: boolean;
}

/** True when some word in the query is not an indexed word or the start of one. */
function hasUnknownWord(engine: MiniSearch<FlatSearchEntry>, query: string): boolean {
  return tokenizeQuery(query).some(
    (word) => engine.search(word, { ...SEARCH_OPTIONS, fuzzy: 0 }).length === 0,
  );
}

// Filler words that should never drive (or appear in) a suggestion. "vs" is
// intentionally absent: it is meaningful in "vs code".
const SUGGEST_STOP_WORDS = new Set([
  "a", "an", "the", "is", "are", "was", "were", "be", "been", "do", "does", "did",
  "how", "what", "whats", "why", "when", "where", "which", "who", "can", "could",
  "should", "would", "will", "i", "me", "my", "we", "you", "your", "it", "its",
  "to", "of", "in", "on", "for", "with", "and", "or", "about", "from", "into",
  "than", "then", "this", "that", "there", "please", "tell", "show", "explain",
  "give", "get", "make", "use", "using", "used",
]);

/**
 * "Did you mean" suggestions. Delegates to MiniSearch's autoSuggest, then
 * cleans the output:
 * - filler words are removed from the input, so long natural-language
 *   questions don't produce suggestions full of "to / and / in";
 * - every suggested word must be a real word from the content (joined index
 *   tokens like "codeextensions" and raw stems are rejected);
 * - every suggestion must actually return results when searched, so we never
 *   offer a click that leads to another empty page.
 */
export function suggestQueries(
  index: FlatSearchEntry[],
  rawQuery: string,
  { limit = 5, misspelledOnly = false }: SuggestOptions = {},
): SearchSuggestion[] {
  const query = normalizeSearch(rawQuery);
  if (query.length < SEARCH_LENGTH) return [];

  const engine = getEngine(index);
  if (misspelledOnly && !hasUnknownWord(engine, query)) return [];

  const queryWords = Array.from(
    new Set(tokenizeQuery(query).map(normalizeSearch).filter((w) => w && !SUGGEST_STOP_WORDS.has(w))),
  );
  const input = queryWords.length > 0 ? queryWords.join(" ") : query;

  const forms = getSurfaceForms(index);
  // Prefer the user's own spelling when a suggested stem matches a typed word
  // ("code" stays "code" instead of becoming "coding").
  const typed = new Map<string, string>();
  for (const word of queryWords) {
    const stem = processTerm(word);
    if (stem && !typed.has(stem)) typed.set(stem, word);
  }
  const best = new Map<string, number>();

  for (const { suggestion, score } of engine.autoSuggest(input, SUGGEST_OPTIONS)) {
    const stems = suggestion.split(" ");
    if (new Set(stems).size !== stems.length) continue;

    const words = stems.map((stem) => typed.get(stem) ?? forms.get(stem));
    if (words.some((word) => !word)) continue;

    const readable = words.join(" ");
    if (normalizeSearch(readable) === query || readable === input) continue;
    if (score > (best.get(readable) ?? -Infinity)) best.set(readable, score);
  }

  // Suggestions that keep more of what the user typed come first; score breaks ties.
  const typedWords = new Set(queryWords);
  const kept = (text: string) => text.split(" ").filter((w) => typedWords.has(w)).length;

  const ranked = Array.from(best, ([suggestion, score]) => ({ suggestion, score })).sort(
    (a, b) => kept(b.suggestion) - kept(a.suggestion) || b.score - a.score,
  );

  const valid: SearchSuggestion[] = [];
  for (const candidate of ranked) {
    if (engine.search(candidate.suggestion, { ...SEARCH_OPTIONS, fuzzy: 0 }).length === 0) continue;
    valid.push(candidate);
    if (valid.length >= limit) break;
  }

  return valid;
}

/* ============================ RESULT SHAPING ============================ */

/**
 * Groups MiniSearch hits back into their parent course, sorts routes and
 * groups by score, and applies the result limit. Purely a reshaping step —
 * all ranking decisions were already made by MiniSearch.
 *
 * Each group also carries the course's `firstTopicPath` (or `link`, for
 * external courses) so the caller can build a course-level link that goes
 * straight into the course's first topic instead of a bare, topic-less
 * course page — mirroring the course's topic ordering.
 *
 * Note: MiniSearch scores are "higher is better" (unlike Fuse's 0–1,
 * lower-is-better scale), so results here are sorted in descending order.
 */

function groupResults(hits: MiniSearchHit[], limit: number): SearchResult[] {
  const grouped = new Map<string, SearchResult>();

  for (const hit of hits) {
    const category = hit.category as string;
    const name = hit.name as string;
    const topic = hit.topic as string | undefined;
    const firstTopic = hit.firstTopic as string | undefined;
    const firstTopicPath = hit.firstTopicPath as string | undefined;
    const link = hit.link as string | undefined;
    const path = hit.path as string | undefined;
    const { score } = hit;

    const key = `${category}::${name}`;

    let group = grouped.get(key);
    if (!group) {
      group = { category, name, routes: [], score, firstTopic, firstTopicPath, link };
      grouped.set(key, group);
    }

    group.score = Math.max(group.score, score);
    if (topic && path) group.routes.push({ topic, path, score });
    if (!group.firstTopic && firstTopic) group.firstTopic = firstTopic;
    if (!group.firstTopicPath && firstTopicPath) group.firstTopicPath = firstTopicPath;
    if (!group.link && link) group.link = link;
  }

  const results = Array.from(grouped.values());

  results.forEach((group) => {
    group.routes.sort((a, b) => b.score - a.score || a.topic.localeCompare(b.topic));
  });

  results.sort((a, b) => b.score - a.score || a.name.localeCompare(b.name));

  let remaining = limit;

  return results
    .map((group) => {
      if (remaining <= 0) return null;

      const routes = group.routes.slice(0, remaining);
      remaining -= routes.length;

      return { ...group, routes };
    })
    .filter((group): group is SearchResult => group !== null);
}

