/* ---- AI retrieval tuning ---- */

/** Topic pages handed to the model (whole-course entries come on top of this). */
const AI_TOPIC_LIMIT = 30;
/** Whole-course entries added, so "suggest a course" has real courses to choose from. */
const AI_COURSE_LIMIT = 6;
/** One huge course (say 300 CSS topics) must not push every other course out of the list. */
const AI_PER_COURSE_CAP = 8;
/** Matches counted per search term: the long tail of weak matches is only noise. */
const AI_HITS_PER_TERM = 60;
/** How many of the AI's keywords are searched. */
const AI_MAX_KEYWORDS = 15;
/** The AI's keywords are trusted a little less than the user's own words. */
const AI_KEYWORD_WEIGHT = 0.9;
/** A course is only listed if it scored at least this share of the best course. */
const AI_COURSE_MIN_SHARE = 0.25;

export interface RetrieveForAiOptions {
  /**
   * Search terms the AI derived from the question and any attached image, most
   * important first (see the topic lookup in the API route). They are searched
   * on top of the user's own words, so the right pages are found even when the
   * words differ from the page titles ("anchor tag" vs "HTML Link Page") or
   * when there are no words at all (an image).
   */
  topics?: string[];
  /** Topic pages returned. Whole-course entries are added on top. Default 30. */
  limit?: number;
}

const toAiCandidate = (hit: MiniSearchHit): AiCandidate => ({
  category: hit.category as string,
  name: hit.name as string,
  topic: (hit.topic as string | undefined) || undefined,
  firstTopic: (hit.firstTopic as string | undefined) || undefined,
  firstTopicPath: (hit.firstTopicPath as string | undefined) || undefined,
  path: (hit.path as string | undefined) || undefined,
  link: (hit.link as string | undefined) || undefined,
  description: typeof hit.description === "string" ? hit.description : "",
});

/**
 * Finds the pages most relevant to a free-form question, to be handed to the
 * model as grounding context.
 *
 * Every search is a "vote": each page earns up to `weight` points per search,
 * scaled against that search's best hit, and the votes are added up. So a page
 * found by many of the AI's keywords ("html", "link", "hyperlink", "href")
 * beats a page that only shares one word with the question.
 *
 * 1. The user's own words. `searchContent` requires *every* word to match,
 *    which returns nothing for a sentence like "how do I use hooks in react?",
 *    so here stop words are dropped, synonyms are added, and the rest is OR-ed.
 * 2. Each of the AI's `topics` keywords, searched on its own.
 *
 * The result is the best topic pages (at most `AI_PER_COURSE_CAP` per course)
 * plus one whole-course entry for each of the best courses, listing the
 * matching topics, so the model can recommend a course, not only single pages.
 */
export function retrieveForAI(
  index: FlatSearchEntry[],
  rawQuestion: string,
  { topics = [], limit = AI_TOPIC_LIMIT }: RetrieveForAiOptions = {},
): AiCandidate[] {
  const engine = getEngine(index);
  const votes = new Map<string, { hit: MiniSearchHit; score: number }>();

  const vote = (hits: MiniSearchHit[], weight: number) => {
    const best = hits[0]?.score;
    if (!best) return;

    for (const hit of hits.slice(0, AI_HITS_PER_TERM)) {
      const entry = votes.get(hit.id) ?? { hit, score: 0 };
      entry.score += weight * (hit.score / best);
      votes.set(hit.id, entry);
    }
  };

  // 1. The user's own words.
  const terms = normalizeSearch(rawQuestion)
    .split(/\s+/)
    .filter((word) => word && !AI_STOP_WORDS.has(word));

  if (terms.length > 0) {
    const expanded = new Set(terms);
    for (const term of terms) {
      SYNONYM_MAP.get(term)?.forEach((synonym) => expanded.add(synonym));
    }
    vote(
      engine.search(Array.from(expanded).join(" "), { ...SEARCH_OPTIONS, combineWith: "OR" as const }),
      1,
    );
  }

  // 2. The AI's keywords, one search each (all words of a phrase must match),
  //    with the first (most important) keywords counting a little more.
  topics.slice(0, AI_MAX_KEYWORDS).forEach((keyword, position) => {
    const query = normalizeSearch(keyword);
    if (query.length < 2) return;
    vote(engine.search(query, SEARCH_OPTIONS), AI_KEYWORD_WEIGHT / (1 + position * 0.1));
  });

  if (votes.size === 0) return [];

  const ranked = Array.from(votes.values()).sort((a, b) => b.score - a.score);
  const courseKey = (hit: MiniSearchHit) => `${hit.category}::${hit.name}`;

  // Topic pages, best first, with a cap per course.
  const perCourse = new Map<string, number>();
  const picked: MiniSearchHit[] = [];
  for (const { hit } of ranked) {
    const key = courseKey(hit);
    const used = perCourse.get(key) ?? 0;
    if (used >= AI_PER_COURSE_CAP) continue;

    perCourse.set(key, used + 1);
    picked.push(hit);
    if (picked.length >= limit) break;
  }

  // Whole courses: a course's score is its five best pages added together.
  const courses = new Map<
    string,
    { hit: MiniSearchHit; score: number; counted: number; topics: string[]; hasCourseEntry: boolean }
  >();
  for (const { hit, score } of ranked) {
    const key = courseKey(hit);
    let course = courses.get(key);
    if (!course) {
      course = { hit, score: 0, counted: 0, topics: [], hasCourseEntry: false };
      courses.set(key, course);
    }

    if (!hit.topic) course.hasCourseEntry = true;
    if (course.counted < 5) {
      course.score += score;
      course.counted += 1;
    }
    if (hit.topic && course.topics.length < 6) course.topics.push(hit.topic as string);
  }

  const bestCourseScore = Math.max(...Array.from(courses.values(), (course) => course.score));
  const courseEntries: AiCandidate[] = Array.from(courses.values())
    // A course that already has its own entry in the results needs no summary.
    .filter((course) => !course.hasCourseEntry && course.score >= bestCourseScore * AI_COURSE_MIN_SHARE)
    .sort((a, b) => b.score - a.score)
    .slice(0, AI_COURSE_LIMIT)
    .map(({ hit, topics: names }) => ({
      category: hit.category as string,
      name: hit.name as string,
      firstTopic: (hit.firstTopic as string | undefined) || undefined,
      firstTopicPath: (hit.firstTopicPath as string | undefined) || undefined,
      link: (hit.link as string | undefined) || undefined,
      description: `Full course "${hit.name as string}" (${hit.category as string}). Includes topics such as: ${names.join(", ")}.`.slice(0, 350),
    }));

  return [...courseEntries, ...picked.map(toAiCandidate)];
}

/* ================================ PUBLIC ================================ */

/**
 * Searches the flat index against a query using MiniSearch, then groups
 * matches back into their parent course. A route is included if its own
 * topic, its course name, or its category matches — so searching a course
 * name still surfaces every page in that course (documentation-search
 * behavior), while MiniSearch's field boosts keep topic-level hits ranked
 * above name-level hits.
 */

export function searchContent(
  index: FlatSearchEntry[],
  rawQuery: string,
  limit = 100,
): SearchResult[] {
  const query = normalizeSearch(rawQuery);
  if (query.length < SEARCH_LENGTH) return [];

  const engine = getEngine(index);
  const variants = generateQueryVariants(query);

  // Merge hits across synonym variants, keeping each document's best score
  // so a term matching via its synonym doesn't get double-counted or
  // outrank a direct match.
  const bestHits = new Map<string, MiniSearchHit>();
  for (const variant of variants) {
    for (const hit of engine.search(variant, SEARCH_OPTIONS)) {
      const existing = bestHits.get(hit.id);
      if (!existing || hit.score > existing.score) bestHits.set(hit.id, hit);
    }
  }

  return groupResults(Array.from(bestHits.values()), limit);
}