"use client";

import { useCallback, useRef, useState } from "react";
import { AI_MAX_IMAGES, prepareImage, type AiImage } from "./aiImages";

/**
 * Images the user has attached to their next message. Files are processed
 * (downscaled, compressed) as they're added, in parallel, up to AI_MAX_IMAGES.
 */
export function useImageAttachments() {
  const [images, setImages] = useState<AiImage[]>([]);
  const [error, setError] = useState<string | null>(null);

  // Mirrors of state so concurrent adds can't exceed the limit.
  const countRef = useRef(0);

  const addFiles = useCallback(async (files: File[]) => {
    const candidates = files.filter((file) => file.type.startsWith("image/"));
    if (candidates.length === 0) {
      if (files.length > 0) setError("Only image files can be attached.");
      return;
    }

    const slots = AI_MAX_IMAGES - countRef.current;
    if (slots <= 0) {
      setError(`You can attach up to ${AI_MAX_IMAGES} images.`);
      return;
    }

    const accepted = candidates.slice(0, slots);
    countRef.current += accepted.length;
    setError(
      candidates.length > slots ? `Only ${AI_MAX_IMAGES} images can be attached at once.` : null,
    );

    const results = await Promise.allSettled(accepted.map(prepareImage));
    const ready: AiImage[] = [];
    let failure: string | null = null;

    for (const result of results) {
      if (result.status === "fulfilled") ready.push(result.value);
      else failure = result.reason instanceof Error ? result.reason.message : "Couldn't add that image.";
    }

    // Give back the slots of images that failed to process.
    countRef.current -= accepted.length - ready.length;
    if (failure) setError(failure);
    if (ready.length > 0) setImages((current) => [...current, ...ready]);
  }, []);

  const removeImage = useCallback((id: string) => {
    countRef.current = Math.max(0, countRef.current - 1);
    setImages((current) => current.filter((image) => image.id !== id));
    setError(null);
  }, []);

  const clearImages = useCallback(() => {
    countRef.current = 0;
    setImages([]);
    setError(null);
  }, []);

  return { images, error, addFiles, removeImage, clearImages };
}
