"use client";

import ArticleOutlinedIcon from "@mui/icons-material/ArticleOutlined";
import CloseIcon from "@mui/icons-material/Close";
import OpenInNewIcon from "@mui/icons-material/OpenInNew";
import StarIcon from "@mui/icons-material/Star";
import StarBorderIcon from "@mui/icons-material/StarBorder";
import type { MouseEvent } from "react";
import { describePage, type SavedPage } from "./savedPage";

// Pressing a button normally steals focus from the search input, which would
// silently disable the arrow-key / Escape handling attached to it. Cancelling
// mousedown keeps focus in the input; the click still fires.
const keepInputFocus = (e: MouseEvent<HTMLElement>) => e.preventDefault();

/**
 * True when the browser should handle the click itself (new tab / window /
 * download) instead of us routing in-page. Plain left-click is the only one
 * we intercept.
 */
export const isModifiedClick = (e: MouseEvent<HTMLElement>) =>
  e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey;

interface FavoriteToggleProps {
  isFavorite: boolean;
  /** Name of the page, used for the accessible label. */
  title: string;
  onToggle: () => void;
}

export function FavoriteToggle({ isFavorite, title, onToggle }: FavoriteToggleProps) {
  const label = isFavorite
    ? `Remove "${title}" from favorites`
    : `Add "${title}" to favorites`;

  return (
    <button
      type="button"
      className={`favorite-toggle ${isFavorite ? "active" : ""}`}
      aria-pressed={isFavorite}
      aria-label={label}
      title={isFavorite ? "Remove from favorites" : "Add to favorites"}
      onMouseDown={keepInputFocus}
      onClick={onToggle}
    >
      {isFavorite ? (
        <StarIcon fontSize="small" aria-hidden="true" />
      ) : (
        <StarBorderIcon fontSize="small" aria-hidden="true" />
      )}
    </button>
  );
}

interface PageRowProps {
  page: SavedPage;
  isFavorite: boolean;
  /**
   * Called when the row is opened. `newTab` is true for Ctrl/Cmd/Shift-click
   * and middle-click: the browser opens the link itself, so the handler should
   * only record the visit and must not navigate or close the modal.
   */
  onOpen: (opts: { newTab: boolean }) => void;
  onToggleFavorite: () => void;
  /** When provided, an ✕ button removes the row from its list (used by "Recently visited"). */
  onRemove?: () => void;
}

/** One row in the "Favorites" / "Recently visited" lists of the empty search state. */
export default function PageRow({
  page,
  isFavorite,
  onOpen,
  onToggleFavorite,
  onRemove,
}: PageRowProps) {
  return (
    <li className="recent-item">
      <a
        className="recent-select"
        href={page.path}
        {...(page.external ? { target: "_blank", rel: "noopener noreferrer" } : {})}
        onMouseDown={keepInputFocus}
        onClick={(e) => {
          if (isModifiedClick(e)) {
            onOpen({ newTab: true }); // browser opens the new tab
            return;
          }
          e.preventDefault();
          onOpen({ newTab: false });
        }}
        onAuxClick={(e) => {
          if (e.button === 1) onOpen({ newTab: true }); // middle-click
        }}
      >
        {page.external ? (
          <OpenInNewIcon fontSize="small" aria-hidden="true" />
        ) : (
          <ArticleOutlinedIcon fontSize="small" aria-hidden="true" />
        )}
        <span className="recent-page-text">
          <span className="recent-term">{page.title}</span>
          <span className="recent-page-meta">{describePage(page)}</span>
        </span>
      </a>

      <FavoriteToggle isFavorite={isFavorite} title={page.title} onToggle={onToggleFavorite} />

      {onRemove && (
        <button
          type="button"
          className="recent-remove"
          onClick={onRemove}
          onMouseDown={keepInputFocus}
          aria-label={`Remove "${page.title}" from recently visited`}
          title="Remove"
        >
          <CloseIcon fontSize="small" aria-hidden="true" />
        </button>
      )}
    </li>
  );
}
