"use client";

import { useEffect, useState } from "react";

import AutoAwesomeIcon from "@mui/icons-material/AutoAwesome";
import DarkModeIcon from "@mui/icons-material/DarkMode";
import LightModeIcon from "@mui/icons-material/LightMode";

import { useTheme } from "next-themes";

import "./ThemeSwitcher.css";

type Props = {
  variant?: "pill" | "circle";
};

const ThemeSwitcher = ({ variant = "pill" }: Props) => {
  const { theme, setTheme } = useTheme();

  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  if (!mounted) {
    return (
      <button
        className={variant === "circle" ? "theme-circle" : "theme-btn"}
        aria-label="Switch theme"
      />
    );
  }

  const themes = ["pinktra", "light", "dark"] as const;

  const currentTheme =
    theme === "pinktra" || theme === "light" || theme === "dark" ? theme : "pinktra";

  const nextTheme = () => {
    const index = themes.indexOf(currentTheme);
    setTheme(themes[(index + 1) % themes.length]);
  };

  if (variant === "circle") {
    return (
      <button
        className="theme-circle toggle-button-wh"
        onClick={nextTheme}
        aria-label="Toggle theme"
        title={`Current theme: ${currentTheme}. Click to switch.`}
      >
        {currentTheme === "pinktra" && <AutoAwesomeIcon aria-hidden="true" />}
        {currentTheme === "light" && <LightModeIcon aria-hidden="true" />}
        {currentTheme === "dark" && <DarkModeIcon aria-hidden="true" />}
      </button>
    );
  }

  return (
    <div className="theme-switcher" role="group" aria-label="Choose theme">
      <button
        className={`theme-btn ${currentTheme === "pinktra" ? "active" : ""}`}
        onClick={() => setTheme("pinktra")}
        aria-label="pinktra theme"
        aria-pressed={currentTheme === "pinktra"}
        title="pinktra theme"
      >
        <AutoAwesomeIcon aria-hidden="true" />
      </button>

      <button
        className={`theme-btn ${currentTheme === "light" ? "active" : ""}`}
        onClick={() => setTheme("light")}
        aria-label="Light theme"
        aria-pressed={currentTheme === "light"}
        title="Light theme"
      >
        <LightModeIcon aria-hidden="true" />
      </button>

      <button
        className={`theme-btn ${currentTheme === "dark" ? "active" : ""}`}
        onClick={() => setTheme("dark")}
        aria-label="Dark theme"
        aria-pressed={currentTheme === "dark"}
        title="Dark theme"
      >
        <DarkModeIcon aria-hidden="true" />
      </button>
    </div>
  );
};

export default ThemeSwitcher;
