"use client";

import CheckIcon from "@mui/icons-material/Check";
import PaletteIcon from "@mui/icons-material/Palette";
import { useTheme } from "next-themes";
import { useEffect, useMemo, useRef, useState } from "react";
import { SYNTAX_THEMES, type SyntaxTheme } from "./syntax-themes";
import "./SyntaxThemeSwitcher.css";

const THEMES = Object.keys(SYNTAX_THEMES) as SyntaxTheme[];

const STORAGE_KEY = "pinktra-syntax-theme";

/** A "choice" is either an explicit theme, or "auto" (follow app theme). */
type ThemeChoice = SyntaxTheme | "auto";

function resolveAutoTheme(appTheme: string | undefined): SyntaxTheme {
  switch (appTheme) {
    case "light":
      return "ayu-light";
    case "dark":
      return "ayu-dark";
    case "pinktra":
    default:
      return "aurora-x";
  }
}

function applySyntaxTheme(theme: SyntaxTheme) {
  const html = document.documentElement;

  THEMES.forEach((t) => {
    html.classList.remove(`syntax-${t}`);
  });

  html.classList.add(`syntax-${theme}`);
}

function saveSyntaxChoice(choice: ThemeChoice) {
  localStorage.setItem(STORAGE_KEY, choice);
}

function loadSyntaxChoice(): ThemeChoice {
  const saved = localStorage.getItem(STORAGE_KEY);

  if (saved === "auto") return "auto";
  if (saved && saved in SYNTAX_THEMES) return saved as SyntaxTheme;

  // No saved preference yet -> default to auto.
  return "auto";
}

export default function SyntaxThemeSwitcher() {
  // What the user picked: an explicit theme, or "auto".
  const [choice, setChoice] = useState<ThemeChoice>("auto");
  const [open, setOpen] = useState(false);
  const [search, setSearch] = useState("");
  const { theme: appTheme } = useTheme();

  // next-themes can't know the real theme during SSR (and its value may
  // already differ from the server on the client's very first render,
  // e.g. once it reads localStorage) — so until we're mounted, pretend
  // appTheme is unresolved. This keeps the first client render identical
  // to the server-rendered HTML and avoids a hydration mismatch on the
  // aria-label/text below, which otherwise flips from the "auto" default
  // ("aurora-x") to the actual stored theme mid-hydration.
  const [mounted, setMounted] = useState(false);

  const wrapperRef = useRef<HTMLDivElement>(null);

  // The theme actually painted on screen right now.
  const resolvedTheme = useMemo<SyntaxTheme>(
    () => (choice === "auto" ? resolveAutoTheme(mounted ? appTheme : undefined) : choice),
    [choice, appTheme, mounted],
  );

  useEffect(() => {
    setMounted(true);
  }, []);

  // Load saved choice once on mount.
  useEffect(() => {
    setChoice(loadSyntaxChoice());
  }, []);

  // Re-apply the class any time the resolved theme changes. When choice is
  // "auto" this also fires on appTheme changes, so switching light/dark
  // keeps following automatically instead of freezing on first load.
  useEffect(() => {
    applySyntaxTheme(resolvedTheme);
  }, [resolvedTheme]);

  useEffect(() => {
    const close = (e: MouseEvent) => {
      if (wrapperRef.current && !wrapperRef.current.contains(e.target as Node)) {
        setOpen(false);
        setSearch("");
      }
    };

    document.addEventListener("mousedown", close);

    return () => {
      document.removeEventListener("mousedown", close);
    };
  }, []);

  const filtered = useMemo(() => {
    const q = search.toLowerCase();

    const items: { id: ThemeChoice; label: string }[] = [
      { id: "auto", label: "Auto" },
      ...THEMES.map((id) => ({ id, label: SYNTAX_THEMES[id].label })),
    ];

    return items
      .filter((item) => item.label.toLowerCase().includes(q))
      .filter((item) => item.id !== choice);
  }, [search, choice]);

  const changeChoice = (value: ThemeChoice) => {
    setChoice(value);
    saveSyntaxChoice(value);
    setOpen(false);
    setSearch("");
  };

  const currentLabel =
    choice === "auto"
      ? `Auto (${SYNTAX_THEMES[resolvedTheme].label})`
      : SYNTAX_THEMES[choice].label;

  return (
    <div
      className="syntax-theme toggle-button toggle-button-wh"
      ref={wrapperRef}
      role="button"
      tabIndex={0}
      aria-label={`Code theme: ${currentLabel}`}
      aria-expanded={open}
      aria-haspopup="listbox"
      title="Select code theme"
      onClick={() => setOpen((v) => !v)}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          setOpen((v) => !v);
        }
        if (e.key === "Escape") {
          setOpen(false);
          setSearch("");
        }
      }}
    >
      <PaletteIcon fontSize="small" aria-hidden="true" />
      {/* Prevent click event from bubbling to parent/document. 
          Otherwise the outside-click
          handler will immediately close the dropdown. */}
      {open && (
        <div
          className="syntax-theme-dropdown"
          role="listbox"
          aria-label="Code themes"
          onClick={(e) => e.stopPropagation()}
        >
          <input
            placeholder="Search theme..."
            value={search}
            aria-label="Search themes"
            onChange={(e) => {
              e.stopPropagation();
              setSearch(e.target.value);
            }}
          />

          <div className="syntax-theme-list">
            <div className="syntax-theme-section-title" aria-hidden="true">
              Code Theme
            </div>

            <button
              className="syntax-theme-item active"
              onClick={() => changeChoice(choice)}
              role="option"
              aria-selected={true}
            >
              <span>{currentLabel}</span>

              <CheckIcon fontSize="small" aria-hidden="true" />
            </button>

            <div className="syntax-theme-divider" aria-hidden="true" />

            {filtered.map((item) => (
              <button
                key={item.id}
                className="syntax-theme-item"
                onClick={() => changeChoice(item.id)}
                role="option"
                aria-selected={false}
              >
                <span>{item.label}</span>
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}