"use client";

import AddPhotoAlternateOutlinedIcon from "@mui/icons-material/AddPhotoAlternateOutlined";
import ArrowUpwardIcon from "@mui/icons-material/ArrowUpward";
import CloseIcon from "@mui/icons-material/Close";
import PsychologyIcon from "@mui/icons-material/Psychology";
import PsychologyOutlinedIcon from "@mui/icons-material/PsychologyOutlined";
import StopIcon from "@mui/icons-material/Stop";
import {
  useCallback,
  useEffect,
  useRef,
  type ChangeEvent,
  type KeyboardEvent,
  type MouseEvent,
  type MutableRefObject,
} from "react";
import { AI_IMAGE_ACCEPT, AI_MAX_IMAGES, type AiImage } from "./aiImages";
import { AI_MAX_QUESTION_LENGTH } from "./aiSearch";

// Keep focus in the text box when these buttons are pressed (the click still fires).
const keepFocus = (e: MouseEvent<HTMLElement>) => e.preventDefault();

/** One line of text: 20px line height + 7px padding top and bottom. Must match the CSS. */
const MIN_HEIGHT = 34;
/** Tallest the box grows (in px) before it scrolls internally. */
const MAX_HEIGHT = 140;

interface SearchAiInputProps {
  value: string;
  placeholder: string;
  inputRef: MutableRefObject<HTMLTextAreaElement | null>;
  images: AiImage[];
  busy: boolean;
  canSend: boolean;
  /** "Thinking" mode: the AI first works out the topic (2 AI calls) for better matches. */
  thinking: boolean;
  onToggleThinking: () => void;
  onChange: (value: string) => void;
  onSend: () => void;
  onStop: () => void;
  onEscape: () => void;
  onPickFiles: (files: File[]) => void;
  onRemoveImage: (id: string) => void;
}

/**
 * The chat input pinned to the bottom of AI mode: attached images on top, then
 * one rounded box with the attach button on the left, an auto-growing text
 * area, and the send / stop button inside it on the right.
 * Enter sends, Shift+Enter adds a new line.
 */
export default function SearchAiInput({
  value,
  placeholder,
  inputRef,
  images,
  busy,
  canSend,
  thinking,
  onToggleThinking,
  onChange,
  onSend,
  onStop,
  onEscape,
  onPickFiles,
  onRemoveImage,
}: SearchAiInputProps) {
  const fileInput = useRef<HTMLInputElement>(null);
  const full = images.length >= AI_MAX_IMAGES;

  const send = () => onSend();

  // Grow with the content, between one line and MAX_HEIGHT.
  const fit = useCallback(() => {
    const el = inputRef.current;
    // Hidden (e.g. the modal is closed): nothing can be measured, so keep the
    // current height rather than collapsing to 0.
    if (!el || el.offsetWidth === 0) return;

    el.style.height = "auto";
    const height = Math.max(MIN_HEIGHT, Math.min(el.scrollHeight, MAX_HEIGHT));
    el.style.height = `${height}px`;
    el.style.overflowY = el.scrollHeight > MAX_HEIGHT ? "auto" : "hidden";
  }, [inputRef]);

  useEffect(fit, [value, fit]);

  // The box can mount while the modal is hidden (the last mode is restored on
  // load), so measure again once it becomes visible or changes width.
  useEffect(() => {
    const el = inputRef.current;
    if (!el || typeof ResizeObserver === "undefined") return;

    let lastWidth = el.offsetWidth;
    const observer = new ResizeObserver(() => {
      if (el.offsetWidth === lastWidth) return;
      lastWidth = el.offsetWidth;
      fit();
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, [inputRef, fit]);

  const handleKeyDown = (e: KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === "Escape") {
      e.preventDefault();
      onEscape();
    } else if (e.key === "Enter" && !e.shiftKey && !e.nativeEvent.isComposing) {
      e.preventDefault();
      if (!busy) send();
    }
  };

  const handleFiles = (e: ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files ?? []);
    e.target.value = ""; // allow picking the same file again
    if (files.length > 0) onPickFiles(files);
  };

  return (
    <div className="ai-input">
      {images.length > 0 && (
        <ul className="ai-thumbs" aria-label="Attached images">
          {images.map((image, i) => (
            <li key={image.id} className="ai-thumb">
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img src={image.previewUrl} alt={`Attached image ${i + 1}: ${image.name}`} />
              <button
                type="button"
                className="ai-thumb-remove"
                onClick={() => onRemoveImage(image.id)}
                onMouseDown={keepFocus}
                aria-label={`Remove attached image ${i + 1}`}
              >
                <CloseIcon fontSize="inherit" aria-hidden="true" />
              </button>
            </li>
          ))}
        </ul>
      )}

      <div className="ai-input-row">
        <input
          ref={fileInput}
          type="file"
          accept={AI_IMAGE_ACCEPT}
          multiple
          hidden
          onChange={handleFiles}
        />

        <button
          type="button"
          className="ai-input-btn"
          onClick={() => fileInput.current?.click()}
          onMouseDown={keepFocus}
          disabled={full}
          aria-label={full ? `Up to ${AI_MAX_IMAGES} images attached` : "Attach an image"}
          title={full ? `Up to ${AI_MAX_IMAGES} images` : "Attach an image (or paste / drop one)"}
        >
          <AddPhotoAlternateOutlinedIcon fontSize="small" aria-hidden="true" />
        </button>

        <button
          type="button"
          className={`ai-input-btn ai-think-btn ${thinking ? "active" : ""}`}
          onClick={onToggleThinking}
          onMouseDown={keepFocus}
          aria-pressed={thinking}
          aria-label="Enable thinking"
          title={
            thinking
              ? "Thinking is on: smarter answers, may take a little longer. Click to turn off."
              : "Turn on thinking for smarter answers (may take a little longer)."
          }
        >
          {thinking ? (
            <PsychologyIcon fontSize="small" aria-hidden="true" />
          ) : (
            <PsychologyOutlinedIcon fontSize="small" aria-hidden="true" />
          )}
        </button>

        <textarea
          ref={inputRef}
          id="search-input"
          className="ai-input-text"
          rows={1}
          value={value}
          placeholder={placeholder}
          maxLength={AI_MAX_QUESTION_LENGTH}
          aria-label="Message Pia"
          enterKeyHint="send"
          autoComplete="off"
          onChange={(e) => onChange(e.target.value)}
          onKeyDown={handleKeyDown}
        />

        {busy ? (
          <button
            type="button"
            className="ai-send stop"
            onClick={onStop}
            onMouseDown={keepFocus}
            aria-label="Stop answering"
            title="Stop"
          >
            <StopIcon fontSize="small" aria-hidden="true" />
          </button>
        ) : (
          <button
            type="button"
            className="ai-send"
            onClick={send}
            onMouseDown={keepFocus}
            disabled={!canSend}
            aria-label="Send"
            title="Send (Enter)"
          >
            <ArrowUpwardIcon fontSize="small" aria-hidden="true" />
          </button>
        )}
      </div>
    </div>
  );
}