"use client";

import { useEffect, useState, type Dispatch, type SetStateAction } from "react";

/**
 * `useState` that remembers its value in localStorage.
 *
 * - SSR-safe: starts at `initial` and restores after mount, so server and
 *   client markup always match.
 * - Nothing is written until the saved value has been read, so the initial
 *   value can never overwrite what was saved.
 * - Never throws (blocked storage, quota errors, corrupted JSON), and a saved
 *   value that fails `isValid` is ignored.
 * - Writing the initial value removes the entry instead of storing it.
 *
 * `isValid` should be a stable reference (a module-level function).
 */
export function usePersistedState<T>(
  key: string,
  initial: T,
  isValid: (value: unknown) => value is T,
): [T, Dispatch<SetStateAction<T>>] {
  const [value, setValue] = useState<T>(initial);
  const [hydrated, setHydrated] = useState(false);

  useEffect(() => {
    try {
      const raw = window.localStorage.getItem(key);
      if (raw !== null) {
        const parsed: unknown = JSON.parse(raw);
        if (isValid(parsed)) setValue(parsed);
      }
    } catch {
      /* unreadable: keep the initial value */
    }
    setHydrated(true);
  }, [key, isValid]);

  useEffect(() => {
    if (!hydrated) return;

    try {
      if (value === initial) window.localStorage.removeItem(key);
      else window.localStorage.setItem(key, JSON.stringify(value));
    } catch {
      /* storage full or unavailable: this is a convenience feature */
    }
    // `initial` is a constant default, not something that should re-trigger a write.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key, value, hydrated]);

  return [value, setValue];
}
