"use client";

import { useCallback } from "react";
import { getPageId, isSavedPage, type SavedPage } from "./savedPage";
import { useStoredList } from "./useStoredList";

export const RECENT_PAGES_KEY = "search:recent-pages";
export const MAX_RECENT_PAGES = 6;

/** Persists pages the user opened from search, most recent first, de-duplicated by path. */
export function useRecentPages() {
  const { items, add, remove, clear } = useStoredList<SavedPage>({
    key: RECENT_PAGES_KEY,
    max: MAX_RECENT_PAGES,
    isValid: isSavedPage,
    getId: getPageId,
  });

  const removeRecentPage = useCallback((path: string) => remove(path), [remove]);

  return {
    recentPages: items,
    addRecentPage: add,
    removeRecentPage,
    clearRecentPages: clear,
  };
}
