"use client";

import { useCallback } from "react";
import { normalizeSearch } from "~/utils/custom_string";
import { SEARCH_LENGTH } from "./const";
import { useStoredList } from "./useStoredList";

export const RECENT_SEARCHES_KEY = "search:recent";
export const MAX_RECENT_SEARCHES = 8;

const isSearchTerm = (value: unknown): value is string =>
  typeof value === "string" && value.trim().length > 0;

/**
 * Persists the user's recent search queries in localStorage.
 * Most recent first, de-duplicated case/accent-insensitively, capped at
 * `MAX_RECENT_SEARCHES`.
 */
export function useRecentSearches() {
  const { items, add, remove, clear } = useStoredList<string>({
    key: RECENT_SEARCHES_KEY,
    max: MAX_RECENT_SEARCHES,
    isValid: isSearchTerm,
    getId: normalizeSearch,
  });

  const addRecentSearch = useCallback(
    (term: string) => {
      const cleaned = term.trim().replace(/\s+/g, " ");
      if (normalizeSearch(cleaned).length < SEARCH_LENGTH) return;
      add(cleaned);
    },
    [add],
  );

  const removeRecentSearch = useCallback((term: string) => remove(normalizeSearch(term)), [remove]);

  return {
    recentSearches: items,
    addRecentSearch,
    removeRecentSearch,
    clearRecentSearches: clear,
  };
}
