export const AI_MAX_IMAGES = 3;
export const AI_IMAGE_ACCEPT = "image/png,image/jpeg,image/webp,image/gif,image/heic,image/heif";

/** Raw file size accepted before we even try to decode it. */
const MAX_INPUT_BYTES = 15 * 1024 * 1024;
/** Longest side after downscaling. Plenty for screenshots and photos. */
const MAX_SIDE = 1536;
/** Base64 length cap per image (~1 MB). The server enforces a slightly higher one. */
const MAX_BASE64_CHARS = 1_400_000;

/** An image ready to send to the model. Always re-encoded as JPEG. */
export interface AiImage {
  id: string;
  name: string;
  mimeType: "image/jpeg";
  /** Base64 payload without the `data:` prefix. */
  data: string;
  /** Full data URL, used only for thumbnails in the UI. */
  previewUrl: string;
}

const makeId = () =>
  typeof crypto !== "undefined" && "randomUUID" in crypto
    ? crypto.randomUUID()
    : Math.random().toString(36).slice(2);

/**
 * Validates an image file, downscales it and re-encodes it as JPEG so the
 * request stays small. Re-encoding through a canvas also strips metadata
 * such as GPS location from photos. Throws an Error with a user-facing message.
 */
export async function prepareImage(file: File): Promise<AiImage> {
  if (!file.type.startsWith("image/")) throw new Error("Only image files can be attached.");
  if (file.size > MAX_INPUT_BYTES) throw new Error("That image is too large (15 MB max).");

  let bitmap: ImageBitmap;
  try {
    bitmap = await createImageBitmap(file);
  } catch {
    throw new Error("Couldn't read that image. Try a PNG, JPEG or WebP.");
  }

  try {
    const scale = Math.min(1, MAX_SIDE / Math.max(bitmap.width, bitmap.height));
    const width = Math.max(1, Math.round(bitmap.width * scale));
    const height = Math.max(1, Math.round(bitmap.height * scale));

    const canvas = document.createElement("canvas");
    canvas.width = width;
    canvas.height = height;
    const context = canvas.getContext("2d");
    if (!context) throw new Error("Couldn't process that image in this browser.");

    // JPEG has no alpha: paint white first so transparent PNGs don't turn black.
    context.fillStyle = "#fff";
    context.fillRect(0, 0, width, height);
    context.drawImage(bitmap, 0, 0, width, height);

    for (const quality of [0.85, 0.7, 0.55]) {
      const previewUrl = canvas.toDataURL("image/jpeg", quality);
      const data = previewUrl.slice(previewUrl.indexOf(",") + 1);
      if (data.length <= MAX_BASE64_CHARS) {
        return { id: makeId(), name: file.name || "image", mimeType: "image/jpeg", data, previewUrl };
      }
    }
  } finally {
    bitmap.close();
  }

  throw new Error("That image is too detailed to send. Try a smaller screenshot.");
}
